INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0936', 'spa', 'Reinar, gobernar como rey; ejercer autoridad real y dominio soberano sobre un pueblo o reino.', 'Reinar, gobernar como rey; ejercer autoridad real y dominio soberano sobre un pueblo o reino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0937', 'spa', 'Real, regio; perteneciente a un rey, ya sea describiendo a una persona de la corte real o algo que posee autoridad regia.', 'Adjetivo que significa ''real'' o ''perteneciente a un rey'', aplicado tanto a personas vinculadas con la realeza como a cosas que poseen dignidad regia. En Juan 4:46, 49, describe a un ''oficial real'' (βασιλικός) cuyo hijo Jesús sana a distancia, un hombre conectado con la corte de Herodes. Hechos 12:20-21 lo emplea para referirse al territorio y las vestiduras ''reales'' de Herodes Agripa. De manera notable, Santiago 2:8 habla de la ''ley real'' —el mandamiento de amar al prójimo— elevándolo como decreto del Rey mismo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0938', 'spa', 'Reina; mujer que reina o posee autoridad real', 'El sustantivo femenino βασίλισσα designa a una mujer que ejerce poder real o soberanía, ya sea como monarca reinante o como reina consorte. En los Evangelios Sinópticos, Jesús invoca a la ''Reina del Sur'' —la reina de Sabá— que viajó para escuchar la sabiduría de Salomón, avergonzando a su generación indiferente (Matt 12:42; Luke 11:31). En Acts 8:27, el eunuco etíope sirve a Candace, reina de los etíopes. Revelation 18:7 lo emplea para describir la autoexaltación de Babilonia: ''Estoy sentada como reina.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0941', 'spa', 'Cargar, llevar o soportar; desde el transporte fisico hasta la resistencia figurada de cargas, e incluso el hurto.', 'Cargar, llevar o soportar; desde el transporte fisico hasta la resistencia figurada de cargas, e incluso el hurto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0942', 'spa', 'Zarza, zarzal; el arbusto espinoso (Rubus) asociado con la aparición de Dios a Moisés en la zarza ardiente.', 'Se refiere a un arbusto espinoso o zarzal, célebremente la zarza que ardía sin consumirse cuando Dios habló a Moisés en el monte Horeb. Tres de sus cinco apariciones en el NT aluden directamente a esa teofanía: Marcos 12:26 y Lucas 20:37 citan ''el pasaje de la zarza'' como prueba de la resurrección, mientras que Hechos 7:30, 35 relata la narrativa del Éxodo. Lucas 6:44 lo usa en un proverbio —''de las zarzas no se recogen higos''— anclándolo en la botánica cotidiana de Palestina. El español ''zarza'' conserva tanto la resonancia botánica como la teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0946', 'spa', 'Abominación, cosa detestable; algo absolutamente repugnante para Dios, especialmente objetos idolátricos o corrupción moral.', 'Designa algo tan repugnante en lo moral o ritual que provoca el rechazo divino: una «abominación» en el sentido más pleno. La Septuaginta lo emplea para ídolos paganos y prácticas cúlticas prohibidas (de ahí la célebre expresión «abominación desoladora»), y el Nuevo Testamento hereda esta carga de significado. Jesús cita la profecía de Daniel sobre la «abominación desoladora» en el lugar santo (Mt 24:15; Mr 13:14), señalando un sacrilegio tan ofensivo que desencadena la huida escatológica. Lucas 16:15 amplía el sentido para incluir lo que los hombres estiman pero Dios detesta. En Apocalipsis 17:4–5, Babilonia la grande sostiene una copa «llena de abominaciones» y lleva en la frente el título «madre de las abominaciones».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0948', 'spa', 'aborrecer, detestar, sentir repugnancia hacia, considerar abominable', 'Este verbo expresa fuerte repulsión y aborrecimiento, describiendo originalmente el disgusto físico que se siente hacia comida echada a perder pero expandiéndose a la abominación moral y espiritual. El rango clásico incluye sentir náuseas por algo o hacer que algo se vuelva abominable. En el Nuevo Testamento, Pablo lo usa para desafiar al judío que ''aborrece los ídolos'' pero comete sacrilegio (Romanos 2:22), mientras que Apocalipsis describe ''los abominables'' entre aquellos excluidos de la ciudad santa (Apocalipsis 21:8). La palabra aparece en forma de participio pasivo perfecto en Apocalipsis, enfatizando el estado establecido y completado de ser abominable—no un lapso temporal sino un carácter fijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0949', 'spa', 'Firme, seguro, estable; lo que es constante, confiable e inquebrantable, aplicado a promesas, esperanza y posición espiritual.', 'Βέβαιος transmite la cualidad de algo que se mantiene firme bajo presión: estable, garantizado, que no cede. Derivado de βαίνω (''caminar, estar de pie''), evoca un terreno lo suficientemente sólido como para soportar peso. En el Nuevo Testamento, caracteriza las promesas de Dios (Ro 4:16, la promesa es ''firme'' para toda la descendencia de Abraham), la esperanza del creyente (He 3:6, 14; 6:19) y la palabra profética (2 P 1:19). Hebreos 2:2 llama ''firme'' a la ley pronunciada por ángeles, en el sentido de legalmente vinculante y ejecutable. La imagen subyacente es la de algo vacilante que queda asentado sobre terreno sólido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0950', 'spa', 'Confirmar, establecer o afianzar; validar una promesa, asegurar una posición o ratificar lo declarado.', 'Verbo que significa hacer algo firme, seguro o válido. En sus usos activos, describe a Dios o a Cristo confirmando una palabra o promesa: en Marcos 16:20 el Señor confirma la predicación de los discípulos con señales, y en Romanos 15:8 Cristo confirma las promesas hechas a los patriarcas. En construcciones pasivas, el sujeto es quien queda establecido o afianzado, como en Colosenses 2:7, donde los creyentes están ''arraigados y sobreedificados en él, confirmados en la fe''. El verbo transmite la imagen de algo vacilante que es puesto sobre suelo firme.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0951', 'spa', 'confirmación, ratificación, establecimiento legal, hacer firme o seguro', 'Este sustantivo denota el acto de confirmar o establecer algo firmemente, usado en griego clásico para confirmar decisiones o proveer garantía legal. En las dos apariciones del Nuevo Testamento, describe la confirmación o establecimiento de realidades espirituales. Pablo habla de la participación de los creyentes en el evangelio ''tanto en mi prisión como en la confirmación del evangelio'' (Filipenses 1:7), mientras Hebreos nota que un juramento provee ''confirmación'' para terminar disputas (Hebreos 6:16). La palabra sugiere hacer algo seguro, legalmente vinculante o fuera de duda—eliminando incertidumbre y estableciendo la verdad firmemente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0952', 'spa', 'Profano, irreverente; accesible a todos (no sagrado), por tanto común, impío o ritualmente impuro.', 'Describe lo que es ''pisable'' —terreno abierto en contraposición al espacio sagrado— y por extensión lo que es común, impío o irreverente. En las Epístolas Pastorales, Pablo advierte contra las ''fábulas profanas y de viejas'' (1 Tim 4:7) y las ''profanas y vanas palabrerías'' (1 Tim 6:20; 2 Tim 2:16), usando el término para señalar discursos que profanan lo que debería ser santo. En 1 Tim 1:9 caracteriza a personas inicuas junto con los ''impíos'', y Hebreos 12:16 lo aplica a Esaú como arquetipo del profano que cambió su primogenitura sagrada por una comida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0953', 'spa', 'profanar, desacralizar, violar lo sagrado, tratar lo santo como común', 'Este verbo significa profanar o desacralizar algo sagrado, tratando lo santo como común o contaminando lo que debe permanecer puro. La Septuaginta lo usa para violar el sábado o profanar cosas santas, y este uso continúa en el Nuevo Testamento. Jesús menciona cómo los sacerdotes del templo ''profanan el sábado'' con su trabajo necesario pero permanecen sin culpa (Mat 12:5), mientras que los acusadores de Pablo afirman que intentó ''profanar el templo'' (Hch 24:6). La palabra captura la grave violación de cruzar los límites entre lo sagrado y lo profano, aunque el uso de Jesús muestra que la profanación ritual puede justificarse por obligaciones superiores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0954', 'spa', 'Beelzeboul, nombre del príncipe de los demonios; título aplicado a Satanás en los Evangelios Sinópticos.', 'Nombre aplicado al gobernante de los demonios, empleado exclusivamente en los Evangelios Sinópticos durante las controversias sobre el origen del poder exorcístico de Jesús. Su etimología probablemente deriva del hebreo ba’al zebul («señor de la morada») o de una distorsión deliberada del Baal-zebub («señor de las moscas») veterotestamentario de 2 Reyes 1:2. En Mateo 12:24–27 y Marcos 3:22, los fariseos acusan a Jesús de expulsar demonios por medio de Beelzeboul, lo que provoca su célebre réplica sobre la «casa dividida». En Mateo 10:25, Jesús advierte que si al dueño de la casa lo llaman Beelzeboul, cuánto más a los de su familia. El término se mantiene como préstamo extranjero indeclinable en todas las tradiciones de traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0956', 'spa', 'proyectil, flecha, dardo, arma arrojadiza, metafóricamente cualquier ataque o prueba', 'Este sustantivo originalmente denotaba cualquier proyectil o misil, especialmente flechas y dardos, pero el griego clásico lo extendió a cualquier arma arrojadiza incluyendo rocas, jabalinas o incluso muebles usados como armas. Homero lo usó para los instrumentos de Apolo trayendo muerte súbita. En el Nuevo Testamento, la palabra aparece en dos contextos muy diferentes: Lucas 18:25 contiene una variante textual que lee ''aguja'' (belonēs) en lugar del más común rhaphidos, mientras que Efesios 6:16 usa ''flechas'' metafóricamente para ''los dardos encendidos del maligno''. El rango semántico desde proyectiles literales hasta ataques espirituales metafóricos muestra la flexibilidad de la palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0958', 'spa', 'Benjamín, el hijo menor de Jacob; una tribu israelita', 'Benjamín es el nombre hebreo del hijo menor de Jacob, cuyos descendientes formaron una de las doce tribus de Israel. En el NT, el nombre aparece en contextos de identidad israelita y herencia tribal. Pablo se identifica dos veces como perteneciente a la tribu de Benjamín (Rom 11:1; Phil 3:5), subrayando su linaje israelita puro. Acts 13:21 recuerda al rey Saúl como benjaminita, y Revelation 7:8 incluye a Benjamín entre las tribus selladas. La forma griega indeclinable refleja el hebreo original Binyāmîn.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0959', 'spa', 'Berenice, hija de Herodes Agripa I, acompañante de su hermano Agripa II', 'Este nombre propio se refiere a Berenice (también Bernice), hija de Herodes Agripa I. Aparece en Hechos acompañando a su hermano Agripa II cuando este llega a saludar a Festo (Hch 25:13). Está presente cuando Festo expone el caso de Pablo ante Agripa (25:23) y cuando Pablo pronuncia su defensa ante ambos (26:30). Las fuentes históricas señalan que vivía con su hermano en una relación que suscitó escándalo. Lucas, con sobriedad narrativa, simplemente registra su presencia en estos procedimientos donde Pablo testificó ante la realeza judía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0960', 'spa', 'Berea, ciudad de Macedonia conocida por sus habitantes de mente noble', 'Este nombre propio identifica a Berea (moderna Veria), una ciudad significativa en el suroeste de Macedonia donde Pablo y Silas predicaron después de huir de Tesalónica. Hechos elogia a los judíos bereanos como ''más nobles que los de Tesalónica'' porque recibieron la palabra con entusiasmo y examinaban las Escrituras diariamente para verificar la enseñanza de Pablo (Hch 17:10-15). La ciudad se hizo conocida en la tradición cristiana por esta respuesta ejemplar a la predicación apostólica. Ambas apariciones neotestamentarias ocurren en la misma narrativa, describiendo la llegada de Pablo y Silas a Berea y la posterior llegada de agitadores tesalonicenses que los persiguieron hasta allí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0962', 'spa', 'Betábara, nombre de lugar que significa ''lugar del cruce'', lectura variante en Juan 1:28', 'Nombre propio geográfico procedente del hebreo (בֵּית עֲבָרָה), que significa ''casa del cruce'' o ''lugar del paso''. Esta localidad aparece como lectura variante en Juan 1:28 en el Texto Recibido, identificando el sitio donde Juan bautizaba. El nombre sugiere un vado o punto de cruce del río, lo cual concuerda con el contexto del ministerio bautismal de Juan. Los textos críticos modernos suelen preferir ''Betania'' para este lugar, lo que convierte a Betábara en una lectura textualmente disputada que refleja antiguas tradiciones escribales sobre el escenario geográfico de la obra de Juan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0963', 'spa', 'Betania — aldea en el Monte de los Olivos cerca de Jerusalén; también un lugar al este del Jordán donde Juan bautizaba', 'Betania — aldea en el Monte de los Olivos cerca de Jerusalén; también un lugar al este del Jordán donde Juan bautizaba');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0965', 'spa', 'Belén — ''casa del pan'', pueblo al sur de Jerusalén; lugar de nacimiento de David y de Jesús el Mesías.', 'Nombre propio indeclinable transliterado del hebreo בֵּית לֶחֶם (bêth lechem, ''casa del pan''). Este pequeño pueblo de Judea, situado a unos diez kilómetros al sur de Jerusalén, tiene un peso teológico enorme como ciudad natal del rey David y, según Miqueas 5:2, lugar profetizado para el nacimiento del Mesías. El relato del nacimiento en Mateo se centra en Belén: los magos son dirigidos allí (Mt 2:1, 5-6, 8) y la matanza de Herodes apunta a sus niños (Mt 2:16). Lucas registra el viaje de José y María por el censo (Lc 2:4, 15). Juan 7:42 recoge el debate de la multitud sobre si el Cristo debía venir de Belén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0966', 'spa', 'Betsaida, pueblo junto al mar de Galilea asociado con varios discípulos y milagros de Jesús.', 'Topónimo que significa «casa de pesca» en arameo, referido a una población situada en la ribera norte del mar de Galilea o cerca de ella. Fue la ciudad natal de Felipe, Andrés y Pedro (Jn 1:44; 12:21) y escenario de eventos significativos, incluida la alimentación de los cinco mil (Lc 9:10). Jesús pronuncia un «ay» contra ella junto con Corazín por no haberse arrepentido a pesar de presenciar obras poderosas (Mt 11:21; Lc 10:13). El debate académico continúa sobre si existía una sola Betsaida o dos, pero el nombre se conserva de manera consistente en todas las tradiciones de traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0967', 'spa', 'Betfagé, aldea en el Monte de los Olivos cercana a Jerusalén, vinculada a la entrada triunfal de Jesús', 'Betfagé era una pequeña aldea en la ladera oriental del Monte de los Olivos, situada entre Betania y Jerusalén. Su nombre proviene del arameo y significa «casa de higos verdes», lo que refleja el carácter agrícola de la zona. Los tres relatos evangélicos de la entrada triunfal de Jesús en Jerusalén mencionan Betfagé como el lugar donde Jesús envió a sus discípulos a buscar el pollino. La aldea constituía un punto de referencia importante en la ruta de peregrinación de Jericó a Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0968', 'spa', 'Tribunal, sede de juicio; un paso o medida de terreno equivalente a un pie', 'Tribunal, sede de juicio; un paso o medida de terreno equivalente a un pie');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0970', 'spa', 'Fuerza física o violencia; poder coercitivo aplicado contra resistencia', 'El sustantivo βία denota fuerza física bruta o compulsión violenta. En el griego clásico abarcaba desde la fuerza heroica hasta actos de brutalidad, y en el NT sus cuatro apariciones se concentran en Hechos describiendo enfrentamientos tensos. La guardia del templo se contiene de usar violencia al arrestar a los apóstoles (Acts 5:26); los soldados deben cargar a Pablo a la fuerza a través de la multitud (Acts 21:35); y el barco en Malta es destrozado por la violencia de las olas (Acts 27:41). El español ''violencia'' captura plenamente el matiz coercitivo del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0971', 'spa', 'forzar, usar violencia, sufrir violencia, avanzar con fuerza, ser tomado por asalto', 'Este verbo lleva el significado fundamental de usar fuerza o violencia, ya sea activamente (obligar, constreñir) o pasivamente (sufrir violencia, ser dominado). El griego clásico lo usaba para estar presionado en batalla, forzado a la esclavitud o compelido a actuar. Las dos apariciones del Nuevo Testamento aparecen en uno de los dichos más debatidos de la Escritura: Mateo 11:12 declara que ''el reino de los cielos sufre violencia'' (o ''ha estado avanzando con fuerza''), y Lucas 16:16 afirma que ''todos se esfuerzan por entrar en él''. Los eruditos debaten si esto describe oposición violenta al reino o entrada forzosa por buscadores ansiosos. La flexibilidad del verbo permite ambas lecturas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0974', 'spa', 'Librito, diminutivo de «libro», referido a un pequeño rollo o documento escrito', 'Esta forma diminutiva enfatiza el tamaño reducido del rollo o documento escrito. En Apocalipsis, un ángel ordena a Juan tomar y comer un «librito» que sabe dulce como la miel en la boca pero se vuelve amargo en el estómago. El sufijo diminutivo transmite tanto la pequeñez física del objeto como, posiblemente, su intimidad o significado especial. A diferencia del gran rollo sellado de Apocalipsis 5, este librito yace abierto en la mano del ángel, listo para ser consumido e interiorizado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0975', 'spa', 'Βιβλίον, diminutivo de βίβλος (''papiro''), aparece 34 veces en el Nuevo Testamento designando cualquier documento escrito formal — desde una carta de d', 'Βιβλίον, diminutivo de βίβλος (''papiro''), aparece 34 veces en el Nuevo Testamento designando cualquier documento escrito formal — desde una carta de divorcio (Mateo 19:7; Marcos 10:4) hasta el rollo profético de Isaías que Jesús desenrolló en la sinagoga de Nazaret (Lucas 4:17-20). Sus apariciones más impactantes se encuentran en Apocalipsis, donde el rollo sellado que solo el Cordero puede abrir impulsa la narrativa apocalíptica (Apocalipsis 5:1-9), y el libro de la vida determina el destino final (Apocalipsis 20:12; 21:27). La palabra tiende un puente entre lo cotidiano y lo cósmico: el mismo término nombra un documento legal de divorcio y el registro celestial de los redimidos. Las glosas en distintas lenguas — español ''libro'', francés ''livre'', alemán ''Buch'' — convergen en un solo sentido de ''libro/documento''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0976', 'spa', 'Libro, rollo o documento escrito, especialmente Escritura sagrada o autoritativa. Designa un documento escrito en forma de rollo o codice, generalment', 'Libro, rollo o documento escrito, especialmente Escritura sagrada o autoritativa. Designa un documento escrito en forma de rollo o codice, generalmente portador de contenido sagrado o autoritativo. En los Sinopticos se refiere al libro de los Salmos (Lucas 20:42; Hechos 1:20), al libro de Moises (Marcos 12:26) y al registro genealogico de Jesus (Mateo 1:1). Apocalipsis transforma la imagen en un rollo celestial sellado con siete sellos que solo el Cordero puede abrir (Apocalipsis 5:1-5). Las traducciones son notablemente uniformes: espanol ''libro'', hindi ''पुस्तक'', arabe ''سِفر/كِتاب'', coreano ''책'' y suajili ''kitabu/vitabu'' (con el clasico par de clases bantu ki-/vi-).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0978', 'spa', 'Bitinia, provincia romana en el noroeste de Asia Menor en la costa del Mar Negro', 'Este nombre propio designa Bitinia, una próspera provincia romana que ocupaba la esquina noroeste de Asia Menor a lo largo del Mar Negro. La región tenía poblaciones judías significativas y más tarde cristianas. En Hechos, el Espíritu Santo impide a Pablo entrar en Bitinia durante su segundo viaje misionero (Hch 16:7), redirigiéndolo hacia Macedonia. Sin embargo, la apertura de 1 Pedro saluda a creyentes dispersos por Bitinia entre otras provincias (1 Ped 1:1), mostrando que el evangelio finalmente llegó allí. El nombre aparece en forma genitiva en ambas apariciones, indicando ya sea destino (''hacia Bitinia'') u origen (''de Bitinia'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0979', 'spa', 'Vida o manera de vivir; sustento, posesiones — existencia terrenal frente a medios materiales de subsistencia. A diferencia de zoe, que en el Nuevo Te', 'Vida o manera de vivir; sustento, posesiones — existencia terrenal frente a medios materiales de subsistencia. A diferencia de zoe, que en el Nuevo Testamento suele conllevar connotaciones espirituales o eternas, bios es firmemente terrenal. Se divide en dos acepciones que el griego clasico ya distinguia: la vida como experiencia vivida y la vida como recursos materiales. La parabola del sembrador advierte que ''los afanes, las riquezas y los placeres de la vida'' ahogan la palabra (Lucas 8:14), mientras que la viuda en el tesoro del templo echo ''todo el sustento que tenia'' (Marcos 12:44; Lucas 21:4). El espanol capta ambos sentidos con ''vida'', pero tambien emplea ''bienes'' y ''sustento'' para la acepcion material, revelando la distincion que una sola traduccion podria ocultar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0982', 'spa', 'Relativo a la vida cotidiana, a los asuntos prácticos y las preocupaciones ordinarias de la existencia diaria', 'Este adjetivo describe lo que pertenece a la esfera de la existencia humana cotidiana: las preocupaciones prácticas y terrenales que ocupan la atención de las personas. Pablo lo emplea para referirse a los «asuntos ordinarios» de la vida que incluso jueces seculares pueden resolver, contrastándolos con las realidades espirituales más trascendentes que los creyentes deberían estar capacitados para juzgar. En Lucas, Jesús advierte contra los corazones agobiados por los «afanes de esta vida». El término subraya la naturaleza mundana y temporal de estas preocupaciones, no su maldad intrínseca, sino su capacidad de distraer de las prioridades eternas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0984', 'spa', 'dañar, perjudicar, lesionar, impedir, incapacitar', 'Este verbo significa dañar, lesionar o incapacitar, usado en el griego clásico para todo desde lisiar las patas de caballos hasta obstaculizar los planes de alguien. La palabra sugiere impedir que algo funcione correctamente o causar daño que deteriora la operación normal. Ambas apariciones en el Nuevo Testamento involucran contextos sobrenaturales donde el daño esperado notablemente no ocurre. El final más largo de Marcos promete a los creyentes que beber veneno mortal ''no les dañará'' (Marcos 16:18), mientras Lucas describe cómo un demonio arrojó a un hombre al suelo pero partió ''sin haberle dañado'' (Lucas 4:35). El verbo enfatiza la preservación protectora—la ausencia de lesión esperada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0985', 'spa', 'Brotar, germinar o retonar; producir nuevo crecimiento vegetal', 'El verbo βλαστάνω describe el brote o germinación de la vegetación —el momento en que una semilla o rama produce crecimiento nuevo visible. Jesús lo emplea en dos parábolas: el trigo y la cizaña, donde la cosecha brota y da grano (Matt 13:26), y la semilla que crece en secreto, que germina sin conocimiento del sembrador (Mark 4:27). En Hebrews 9:4, la vara de Aarón ''brotó'' como señal milagrosa de designación divina. James 5:18 describe la tierra produciendo su fruto tras la lluvia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0987', 'spa', 'El verbo βλασφημέω abarca todo el espectro del discurso injurioso, desde lo humano hasta lo divino. En su uso neotestamentario principal, describe hab', 'El verbo βλασφημέω abarca todo el espectro del discurso injurioso, desde lo humano hasta lo divino. En su uso neotestamentario principal, describe hablar contra Dios o las cosas sagradas con desprecio — la acusación lanzada contra Jesús cuando perdonó pecados (Marcos 2:7) y la burla de la multitud en la cruz (Mateo 27:39). Pablo advierte que la mala conducta de los creyentes hace que el nombre de Dios ''sea blasfemado entre los gentiles'' (Romanos 2:24), mostrando la dimensión pasiva. Santiago 2:7 extiende la palabra a la difamación del ''buen nombre'' invocado sobre los creyentes, revelando un uso horizontal, dirigido a personas, junto al sentido vertical dominante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0988', 'spa', 'Blasfemia, calumnia — discurso profano o injurioso, especialmente contra Dios.', 'Blasfemia, calumnia — discurso profano o injurioso, especialmente contra Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0989', 'spa', 'Blasfemo, calumnioso; quien habla de manera injuriosa contra Dios o contra otras personas', 'El adjetivo βλάσφημος describe un hablar injurioso, calumnioso o sacrílego, dirigido tanto contra Dios como contra seres humanos. Puede funcionar como sustantivo con el significado de ''blasfemo'' o ''blasfemador''. Pablo confiesa haber sido anteriormente un blasfemo (1 Tim 1:13), mientras que los acusadores de Esteban sobornan testigos para presentar «palabras blasfemas» contra él (Hch 6:11). En la lista de vicios de 2 Timoteo 3:2, aparece entre los rasgos de los impíos de los últimos días. En 2 Pedro 2:11 se contrasta la mesura de los ángeles con quienes profieren juicios blasfemos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0991', 'spa', 'Ver, mirar, percibir visualmente; también guardarse, tener cuidado o dirigir la mirada con atención', 'Βλέπω es el verbo griego cotidiano para la vista física — ver lo que está ante los propios ojos. A diferencia de ὁράω, que a menudo implica percepción o conciencia interior, βλέπω se mantiene cercano al acto mismo de mirar. En los Evangelios describe tanto las sanaciones de ciegos por parte de Jesús (Mt 12:22) como sus advertencias de ''guardarse'' de la levadura de los fariseos (Mc 8:15). Pablo le da profundidad teológica en 2 Co 4:18, contrastando ''las cosas que se ven'' con las invisibles y eternas. El espectro que va desde la simple vista hasta la vigilancia atenta hace de βλέπω una palabra de atención tanto física como espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0994', 'spa', 'Clamar, gritar en alta voz — alzar la voz en proclamación urgente, angustia o declaración profética', 'Clamar, gritar en alta voz — alzar la voz en proclamación urgente, angustia o declaración profética');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0996', 'spa', 'ayuda, auxilio, asistencia, apoyo, socorro, fuerzas auxiliares', 'Este sustantivo denota ayuda o asistencia, con un uso clásico que abarca desde ayuda médica hasta fuerzas auxiliares militares. La palabra enfatiza el apoyo práctico que atiende necesidades o peligros específicos. En Hechos, los marineros usan ''ayudas'' (probablemente cuerdas o cables) para reforzar su barco sacudido por la tormenta (Hechos 27:17), mientras que Hebreos anima a los creyentes a acercarse al trono de Dios para ''recibir misericordia y hallar gracia para ayuda en tiempo de necesidad'' (Hebreos 4:16). Los dos contextos muestran el rango de la palabra: asistencia física/técnica en crisis marítima y auxilio espiritual/divino para los desafíos de la vida. Ambos enfatizan ayuda oportuna y apropiada que satisface necesidad urgente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0997', 'spa', 'Ayudar, acudir en auxilio, socorrer; literalmente ''correr al oír un grito de socorro''.', 'Compuesto expresivo de βοή (grito, clamor) y θέω (correr), que evoca la imagen de alguien que corre a auxiliar al oír un grito de angustia. En los Evangelios aparece en súplicas desesperadas: la mujer sirofenicia clamando ''¡Señor, ayúdame!'' (Mt 15:25), y el padre del muchacho endemoniado rogando ''¡ayúdanos!'' y luego ''¡ayuda mi incredulidad!'' (Mc 9:22, 24). En Hechos surge tanto en una visión como llamado — ''Pasa a Macedonia y ayúdanos'' (Hch 16:9) — como en una escena violenta de multitud (Hch 21:28). Hebreos 2:18 afirma que Cristo puede socorrer a los tentados porque él mismo padeció tentación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G0999', 'spa', 'Foso, hoyo o zanja, usado frecuentemente como metáfora de peligro o ceguera espiritual', 'Un foso u hoyo en la tierra, ya sea natural o hecho por el hombre. En la enseñanza de Jesús, la imagen se vuelve proverbial: un pastor que rescata a su oveja caída en un hoyo en sábado, o la advertencia de que si un ciego guía a otro ciego, ambos caerán en un hoyo. El término evoca peligro, atrapamiento y la necesidad de rescate. El foso funciona como una metáfora vívida del peligro espiritual, particularmente el riesgo de seguir a guías falsos o incompetentes que no pueden ver el peligro que tienen por delante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1001', 'spa', 'echar la sonda, sondar, medir la profundidad del agua con una línea con plomo', 'Este verbo náutico especializado significa tomar sondeos echando la sonda—lanzar una línea con peso para medir la profundidad del agua. Los marineros antiguos usaban esta técnica al acercarse a la costa o navegar aguas peligrosas para evitar encallar. Ambas apariciones en el Nuevo Testamento se encuentran en la misma escena dramática: el viaje de naufragio de Pablo a Roma. Mientras el barco deriva hacia la costa rocosa de Malta en la oscuridad, los marineros toman sondeos repetidamente para monitorear su acercamiento a tierra. El verbo captura una habilidad crucial de supervivencia marítima, mostrando cómo los marineros combinaban conocimiento técnico con esperanza desesperada durante la tormenta descrita en Hechos 27.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1002', 'spa', 'proyectil, jabalina; sonda de profundidad; rayo; tirada de dados', 'Sustantivo femenino con varios significados distintos pero relacionados, todos vinculados a objetos que se lanzan o arrojan. En su sentido más básico, designa un proyectil o jabalina, un arma arrojada contra el enemigo. En contexto náutico, se refiere a la sonda de plomo, la línea lastrada que se lanza por la borda para medir la profundidad del agua. En sentido meteorológico, describe los destellos o rayos que son ''lanzados'' desde el cielo. Un uso posterior lo aplica a los dados, tanto a la tirada como a los dados mismos en cuanto objetos que se lanzan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1003', 'spa', 'Booz, terrateniente acaudalado de Belén, pariente redentor de Rut, antepasado de David y de Jesús', 'Booz es el prominente betlemita que aparece en el libro de Rut como el pariente redentor que se casa con Rut la moabita. Su nombre figura en dos genealogías evangélicas que trazan el linaje de Jesús a través de la casa de David. El relato en Rut presenta a Booz como un hombre de riqueza, integridad y fidelidad al pacto, que honra tanto la ley de redención como la dignidad de una viuda extranjera. Su matrimonio con Rut lo convierte en bisabuelo de David y lo sitúa en la línea mesiánica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1005', 'spa', 'norte, el viento del norte, la dirección o región del norte', 'Este sustantivo se refiere al norte, específicamente al viento del norte (Bóreas personificado en la mitología clásica) o la dirección norte. En el griego ático aparece como una forma contracta de Bóreas, el viento norte personificado. El Nuevo Testamento lo usa geográficamente para la dirección cardinal norte. Jesús habla de personas viniendo ''del este y del oeste, y del norte y del sur'' para reclinarse en la fiesta del reino de Dios (Lucas 13:29), mientras que Apocalipsis describe la arquitectura de la Nueva Jerusalén con puertas a cada lado incluyendo ''tres puertas al norte'' (Apocalipsis 21:13). Ambos usos enfatizan completitud y alcance universal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1006', 'spa', 'Alimentar o apacentar ganado (dicho del pastor); en voz media/pasiva, pacer o estar pastando (dicho de los animales).', 'Una palabra pastoral arraigada en el mundo antiguo del pastoreo y el cuidado de animales. En voz activa, describe el trabajo del pastor: alimentar y cuidar el rebaño o la manada. Los porquerizos estaban ''apacentando'' cerdos cuando se desató el episodio del endemoniado gadareno (Mt 8:33; Mr 5:14; Lc 8:34), y Jesús encomienda a Pedro ''apacienta mis corderos'' (Jn 21:15), elevando la palabra al ámbito del pastoreo espiritual. En voz media o pasiva, la perspectiva cambia a los animales mismos: los cerdos estaban ''paciendo'' en la ladera (Mt 8:30; Mr 5:11; Lc 8:32), alimentándose apaciblemente antes del dramático encuentro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1010', 'spa', 'consejero, miembro del concilio, senador, uno que sirve en un concilio gobernante', 'Este sustantivo designa a un miembro de un concilio o cuerpo deliberativo, derivado del verbo que significa deliberar o planear. El griego clásico lo usaba para senadores y miembros de varios concejos cívicos. En el Nuevo Testamento, se refiere específicamente a miembros del Sanedrín, el concilio gobernante judío. Ambas apariciones describen a José de Arimatea, identificado como ''un consejero'' o ''miembro del concilio'' (Marcos 15:43; Lucas 23:50). Este cargo colocó a José entre la élite religiosa y política de Jerusalén, haciendo particularmente significativa su petición audaz del cuerpo de Jesús y su discipulado. La palabra enfatiza su estatus oficial y el coraje requerido para identificarse públicamente con el Jesús crucificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1011', 'spa', 'Deliberar, tomar consejo, planear; resolver un curso de acción tras una reflexión cuidadosa.', 'Verbo de deliberación y toma de decisiones intencional: sopesar opciones, consultar consigo mismo o con otros, y llegar a un plan de acción. La voz media (βουλεύομαι), predominante en el Nuevo Testamento, enfatiza la deliberación personal más que el consejo externo. En Lucas 14:31 un rey «se sienta primero a deliberar» si puede enfrentar un ejército enemigo, como parábola sobre contar el costo del discipulado. El Sanedrín «resolvió» matar a Lázaro junto con Jesús (Juan 11:53; 12:10). Pablo lo usa para defender su sinceridad: «Cuando planifiqué esto, ¿lo hice a la ligera?» (2 Co 1:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1012', 'spa', 'Consejo, propósito, designio — una intención o resolución deliberada, ya sea decreto divino o decisión humana. El sustantivo βουλή designa un plan, pr', 'Consejo, propósito, designio — una intención o resolución deliberada, ya sea decreto divino o decisión humana. El sustantivo βουλή designa un plan, propósito o resolución deliberada: la intención firme que surge de una cuidadosa consideración. En su uso teológicamente más relevante, describe el decreto soberano de Dios: Jesús fue entregado ''por el determinado consejo y anticipado conocimiento de Dios'' (Hch 2:23), y los fariseos que rechazaron el bautismo de Juan ''desecharon el consejo de Dios respecto de sí mismos'' (Lc 7:30). Pablo declara que no rehuyó anunciar ''todo el consejo de Dios'' (Hch 20:27). A nivel humano, José de Arimatea ''no había consentido en el consejo ni en los hechos de ellos'' (Lc 23:51).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1013', 'spa', 'Voluntad, propósito, intención deliberada o deseo, especialmente del plan soberano de Dios', 'Este término enfatiza la intención deliberada y la voluntad con propósito, particularmente en contextos que involucran la voluntad soberana de Dios. No sugiere un mero deseo o preferencia, sino un propósito determinado y un decreto firme. Pablo lo usa en Romanos 9 al hablar de la elección soberana de Dios, preguntando retóricamente quién puede resistir su voluntad. En Hechos, el «propósito» del centurión de salvar a Pablo se ve frustrado por la intención contraria de los soldados. El término conlleva peso: es el consejo establecido y el plan determinado de quien ejerce su voluntad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1014', 'spa', 'El verbo griego βούλομαι expresa el paisaje interior de la voluntad, desde el deseo cotidiano hasta el decreto divino soberano. En la mayoría de sus 3', 'El verbo griego βούλομαι expresa el paisaje interior de la voluntad, desde el deseo cotidiano hasta el decreto divino soberano. En la mayoría de sus 37 apariciones neotestamentarias, simplemente significa ''querer'' o ''desear'' — Pilato queriendo satisfacer a la multitud (Marcos 15:15), Jesús preguntando ''¿Queréis que os suelte al rey de los judíos?'' (Juan 18:39). Pero en un puñado de pasajes teológicamente significativos, βούλομαι asciende a una voluntad deliberada y soberana: la autoridad exclusiva del Padre para revelar al Hijo (Mateo 11:27; Lucas 10:22), y el acto propositivo de Dios al engendrarnos por la palabra de verdad (Santiago 1:18). En español, querer refleja la misma ambiguedad entre deseo casual y determinación resuelta, al igual que el francés vouloir. Un tercer sentido, más restringido, capta la intención planificada — José ''quiso'' repudiar a María en secreto (Mateo 1:19) o Herodes ''planeaba'' sacar a Pedro ante el pueblo (Hechos 12:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1015', 'spa', 'colina, monte pequeño, elevación del terreno, loma', 'Este sustantivo denota una colina o loma, una elevación natural menor que una montaña pero distinta del terreno plano. La Septuaginta lo usa para traducir términos hebreos para colinas, a menudo en pasajes poéticos que describen el paisaje. En el Nuevo Testamento, Lucas lo emplea dos veces en citas. El ministerio preparatorio de Juan el Bautista cumple la profecía de Isaías de que ''todo monte y colina será allanado'' (Lucas 3:5), simbolizando la nivelación de obstáculos ante el Señor. Más adelante, Jesús se refiere a un dicho de que la gente clamará a las colinas para que les cubran en tiempos de juicio divino (Lucas 23:30). Ambos usos llevan peso simbólico más allá de la mera geografía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1016', 'spa', 'Buey, toro, vaca; ganado bovino doméstico, empleado en contextos agrícolas, sacrificiales y proverbiales.', 'El sustantivo griego común para designar un buey o cabeza de ganado, abarcando toros, bueyes y vacas. En el Nuevo Testamento, βοῦς aparece en escenas rurales cotidianas: cinco yuntas de bueyes recién compradas (Lc 14:19), un buey caído en un pozo en sábado (Lc 14:5), un buey desatado y llevado a abrevar (Lc 13:15). También figura en la purificación del templo, donde Jesús expulsa a los que vendían bueyes y ovejas (Jn 2:14-15). Pablo cita dos veces Deuteronomio 25:4: ''No pondrás bozal al buey que trilla'' (1 Co 9:9; 1 Ti 5:18), aplicándolo al derecho de los ministros a ganarse el sustento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1017', 'spa', 'premio, galardón dado al vencedor en juegos atléticos, recompensa por ganar', 'Este sustantivo denota el premio otorgado a los vencedores en competencias atléticas, particularmente en los juegos griegos. La palabra originalmente se refería a la vara o bastón dado como premio, luego se extendió a cualquier recompensa del vencedor. Pablo usa dos veces esta imagen atlética para describir la meta de la vida cristiana. Habla de correr de tal manera que se ''obtenga el premio'' (1 Cor 9:24), y más adelante de ''proseguir hacia la meta al premio del supremo llamamiento de Dios en Cristo Jesús'' (Fil 3:14). La imagen evoca el entrenamiento intenso, el enfoque singular y la determinación competitiva de los atletas antiguos, aplicado a la búsqueda espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1019', 'spa', 'demorar, tardar, detenerse, retrasarse, tomarse tiempo', 'Este verbo significa demorar, tardar o detenerse, derivado del adjetivo que significa lento. Puede usarse transitivamente (demorar algo) o intransitivamente (ser lento en actuar). El Nuevo Testamento lo usa para acción o llegada demorada. Pablo escribe a Timoteo sobre qué hacer ''si me tardo'' en llegar (1 Tim 3:15), proveyendo instrucciones para la conducta de la iglesia en su ausencia. Pedro se dirige a quienes malentienden el regreso demorado del Señor, explicando que ''el Señor no tarda respecto a su promesa'' como algunos cuentan la tardanza, sino que es paciente (2 Ped 3:9). Ambos usos involucran llegadas anticipadas que pueden tomar más tiempo de lo esperado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1021', 'spa', 'Lento, torpe o tardo, especialmente en la percepción mental o la capacidad de respuesta espiritual', 'Este adjetivo describe lentitud, ya sea en el movimiento físico o, más comúnmente en contextos bíblicos, en la percepción mental o espiritual. El término puede indicar torpeza, demora o falta de agudeza. Jesús reprende a los discípulos de Emaús como «tardos de corazón para creer» lo que dijeron los profetas. Santiago aconseja a los creyentes ser «tardos para hablar, tardos para airarse»; aquí la lentitud es una virtud que representa moderación y reflexión. El uso clásico abarca tanto la lentitud literal de movimiento como la torpeza metafórica de la mente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1023', 'spa', 'brazo, especialmente como símbolo de fuerza, poder y acción poderosa de Dios', 'El brazo representa la fuerza física y la capacidad de actuar con poder. En el uso bíblico, sobre todo en citas del Antiguo Testamento, el «brazo del Señor» es una metáfora frecuente del poder soberano de Dios manifestado en la salvación y el juicio. El Magnificat de María celebra cómo Dios «hizo proezas con su brazo». El término evoca imágenes de liberación, poderío militar e intervención divina. Aplicado a Dios, es un antropomorfismo que subraya su poder activo para salvar y juzgar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1024', 'spa', 'Corto, pequeño, poco, breve; denota pequeñez de cantidad, extensión o duración.', 'Adjetivo que significa corto, pequeño o breve, usado frecuentemente de forma adverbial en el Nuevo Testamento para indicar una cantidad pequeña, un tiempo corto o un grado leve. En Hebreos 2:7 y 2:9, citando el Salmo 8, describe a la humanidad hecha «un poco menor» que los ángeles, donde la ambigüedad entre «por poco tiempo» y «en un grado menor» ha generado siglos de debate interpretativo. En Hechos 27:28 marca un intervalo breve de distancia entre sondeos de profundidad. El español refleja esta gama con «poco», «breve» y «por poco».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1025', 'spa', 'Bebé, infante o niño por nacer; también el período de la infancia o la primera niñez.', 'Designa a un niño muy pequeño, ya sea aún en el vientre, recién nacido o en la primera infancia. Lucas lo emplea vívidamente para el niño Juan, aún no nacido, que salta en el vientre de Elisabet (Lc 1:41, 44), y para el recién nacido Jesús acostado en un pesebre (Lc 2:12, 16). En Lucas 18:15 la gente trae sus infantes a Jesús. Una única aparición en 2 Timoteo 3:15 extiende la palabra de manera abstracta para significar ''desde la infancia'', señalando no a un niño concreto sino a una etapa de la vida: Timoteo ha conocido las Sagradas Escrituras desde sus primeros días.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1026', 'spa', 'Llover, enviar lluvia desde el cielo; mojar o humedecer con líquido (especialmente lágrimas).', 'Βρέχω es un verbo griego vívido y sensorial cuyo significado básico es mojar o empapar. En el Nuevo Testamento se divide claramente en dos acepciones que los idiomas de traducción distinguen con consistencia. El sentido meteorológico dominante —«llover» o «hacer llover»— aparece cinco veces, desde la enseñanza de Jesús de que el Padre «hace llover sobre justos e injustos» (Mt 5:45) hasta la imagen apocalíptica de Dios lloviendo fuego y azufre sobre Sodoma (Lc 17:29) y la oración de Elías para que no lloviese (Stg 5:17). Pero en Lucas 7:38 y 7:44 el verbo adquiere un sentido íntimo y físico: la mujer pecadora «comenzó a mojar» los pies de Jesús con sus lágrimas, pasando del cielo a la piel, de lo cósmico a lo personal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1027', 'spa', 'Trueno — el sonido que acompaña a las tormentas; señal teofánica del poder y la majestad divina. El sustantivo βροντή se refiere al trueno tanto como ', 'Trueno — el sonido que acompaña a las tormentas; señal teofánica del poder y la majestad divina. El sustantivo βροντή se refiere al trueno tanto como fenómeno meteorológico natural como manifestación teofánica del poder divino. Jesús dio a Santiago y Juan el sobrenombre de ''Boanerges, hijos del trueno'' (Mr 3:17), quizás aludiendo a su temperamento impetuoso. En Apocalipsis, el trueno se convierte en un elemento recurrente de la liturgia y el juicio celestial: procede del trono de Dios (Ap 4:5; 8:5; 11:19; 16:18), acompaña la apertura de los sellos (Ap 6:1) y anuncia proclamaciones angélicas (Ap 10:3-4; 14:2; 19:6). En Juan 12:29, la multitud confunde la voz del Padre con un trueno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1028', 'spa', 'lluvia, precipitación, agua de lluvia, aguacero', 'Este sustantivo simplemente significa lluvia o precipitación, el agua que cae de las nubes e irriga la tierra. Aunque el griego clásico también lo usaba para otras formas de humedecimiento o irrigación, el Nuevo Testamento lo emplea directamente para la lluvia. Ambas ocurrencias aparecen en la parábola de Jesús de los dos constructores (Mat 7:25, 27). La tormenta que prueba ambas casas incluye ''la lluvia'' cayendo junto con inundaciones y vientos. La repetición enfatiza la naturaleza comprensiva de la tormenta: no solo viento o inundación, sino también lluvia, creando la prueba perfecta de cada fundamento. La palabra misma es simple y literal, aunque su contexto es profundamente simbólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1030', 'spa', 'Crujir de dientes; rechinar o apretar los dientes, expresando angustia, ira o desesperación.', 'Se refiere específicamente al crujir o rechinar de dientes, y aparece casi siempre en la frase fija «llanto y crujir de dientes» en las parábolas de juicio de Jesús. Esta expresión vívida transmite la angustia y la furia de quienes son excluidos del reino. Ocurre siete veces —seis en Mateo y una en Lucas— constituyendo uno de los estribillos más reconocibles de la tradición sinóptica. La unanimidad interlingüística es notable: el español «crujir», el francés «grincement» y el alemán «Knirschen» preservan la imagen específica del rechinar dental en lugar de generalizar al mero sufrimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1033', 'spa', 'Alimento, sustento sólido; aquello que se come como sustento.', 'Alimento, sustento sólido; aquello que se come como sustento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1035', 'spa', 'Alimento, sustento; el acto de comer; corrosion o deterioro (de bienes materiales consumidos por polilla y herrumbre). Sustantivo que abarca todo el a', 'Alimento, sustento; el acto de comer; corrosion o deterioro (de bienes materiales consumidos por polilla y herrumbre). Sustantivo que abarca todo el arco desde lo que se come hasta el acto de comer y lo que corroe. En Juan 6:27 y 6:55, Jesus contrasta el alimento perecedero con el sustento perdurable que el ofrece. En Mateo 6:19-20, la misma palabra cambia drasticamente para significar corrosion o deterioro — la lenta ruina que la polilla y el orin infligen a los tesoros terrenales. Pablo la emplea para el acto de comer en Romanos 14:17, recordando a los creyentes que el reino de Dios no consiste en comida y bebida, sino en justicia, paz y gozo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1036', 'spa', 'hundir, hundirse, sumergir, hacer naufragar, abrumar', 'Este verbo significa hundir o hacer hundir, sumergirse en las profundidades. El griego clásico lo usaba para hundir barcos, ahogar personas o abrumar ciudades con inundaciones. El Nuevo Testamento lo emplea tanto literal como metafóricamente. Lucas describe pescadores cuyos botes ''comenzaron a hundirse'' por la pesca milagrosa (Lucas 5:7), mientras Pablo advierte que quienes desean riquezas ''se hunden en destrucción y perdición'' (1 Tim 6:9). Las formas pasivas en ambos pasajes enfatizan el proceso progresivo: botes comenzando a irse abajo por el peso, personas hundiéndose en ruina por la avaricia. El verbo captura tanto la sumersión física como el abrumamiento metafórico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1038', 'spa', 'curtidor, artesano que prepara pieles de animales para cuero, oficio considerado ritualmente impuro por muchos judíos', 'Un curtidor era un artesano que procesaba pieles de animales para convertirlas en cuero mediante raspado, tratamiento y curado. El oficio exigía contacto frecuente con animales muertos, lo que hacía al curtidor ceremonialmente impuro según las leyes judías de pureza. La disposición de Pedro a hospedarse con Simón el curtidor en Jope señala un cambio importante en su comprensión de la pureza ritual, preparándolo para la visión en la azotea y la posterior visita al gentil Cornelio. La marginación social de este oficio otorga significado teológico a la elección de alojamiento de Pedro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1039', 'spa', 'De lino fino (biso); que describe prendas de tela lujosa, especialmente en la imaginería de Apocalipsis sobre riqueza y pureza.', 'Adjetivo que describe algo hecho de biso, el preciado lino fino del mundo mediterráneo antiguo. En Apocalipsis aparece en dos contrastes vívidos: la vestimenta extravagante de Babilonia (Ap 18:12, 16) y las vestiduras resplandecientes y puras de los santos y los ejércitos celestiales (Ap 19:8, 14). Las cinco apariciones neotestamentarias se concentran en Apocalipsis, donde este material funciona como marcador tanto de lujo extremo como de pureza y justicia, un tejido tan fino que portaba un peso económico y simbólico significativo en el mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1043', 'spa', 'Gabriel, el arcángel cuyo nombre significa ''héroe de Dios'' o ''Dios es mi fortaleza''', 'Este nombre propio, transliterado del hebreo גַּבְרִיאֵל (Gavri''el, ''héroe de Dios'' o ''Dios es mi fortaleza''), identifica a uno de los arcángeles nombrados en las Escrituras. Gabriel aparece en las visiones de Daniel como intérprete de misterios proféticos, y en el Evangelio de Lucas como mensajero de Dios anunciando tanto el nacimiento de Juan el Bautista a Zacarías como la encarnación de Jesús a María. Ambas apariciones neotestamentarias ocurren en Lucas 1: Gabriel se identifica por nombre ante el aterrorizado Zacarías (1:19) y se presenta ante María (1:26). Su auto-identificación enfatiza su autoridad como uno que ''está en la presencia de Dios'', enviado para entregar mensajes de importancia cósmica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1049', 'spa', 'Tesoro del templo; lugar para guardar objetos de valor o recibir ofrendas monetarias en el recinto del templo.', 'Se refiere al área del tesoro dentro del complejo del templo, tanto a los receptáculos donde los fieles depositaban sus ofrendas como, por extensión, a la cámara del tesoro misma. En los relatos sinópticos de la ofrenda de la viuda (Marcos 12:41-43; Lucas 21:1), Jesús observa a la gente echando dinero en el gazofilacio. En Juan 8:20, señala el lugar donde Jesús enseñaba. Es una palabra compuesta de γάζα (''tesoro'', préstamo del persa) y φυλακή (''custodia''), designando literalmente el ''lugar de custodia del tesoro''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1050', 'spa', 'Gayo; nombre propio de varios cristianos primitivos en el NT, un praenomen romano muy común.', 'Nombre personal que aparece en distintos pasajes del NT y que puede referirse a entre dos y cuatro individuos diferentes. Pablo bautizó a un Gayo en Corinto (1 Co 1:14), probablemente el mismo que hospedaba a toda la iglesia (Ro 16:23). Un Gayo de Macedonia fue arrastrado durante el tumulto en Éfeso (Hch 19:29), mientras que otro Gayo, oriundo de Derbe, acompañó a Pablo en sus viajes (Hch 20:4). El apóstol Juan dirige su tercera epístola a un Gayo muy querido (3 Jn 1:1). El nombre era uno de los praenomina romanos más frecuentes, lo que explica su presencia entre los conversos gentiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1051', 'spa', 'Leche; usada literalmente como alimento lácteo y figuradamente para la enseñanza espiritual elemental.', 'Designa la leche tanto en su sentido literal como metafórico. Pablo recurre a la imagen de la leche como alimento básico, contrastándola con el alimento sólido, para describir la enseñanza espiritual elemental frente a la madura (1 Co 3:2; He 5:12-13). También apela al derecho literal de beber leche del rebaño propio como sustento de los obreros pastorales (1 Co 9:7). Pedro emplea la metáfora en sentido positivo, exhortando a los creyentes a desear con anhelo la leche espiritual pura para crecer en la fe (1 P 2:2). En todos los contextos, la palabra abarca tanto la sustancia física como su uso figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1053', 'spa', 'Galacia, región y provincia romana en el centro de Asia Menor', 'Galacia designa un territorio en el centro de Asia Menor, originalmente poblado por tribus celtas (galas) que migraron allí en el siglo III a.C. y que más tarde fue incorporado como provincia romana más amplia. Pablo fundó iglesias en esa región y les dirigió su Epístola a los Gálatas (Gál 1:2), además de organizar una colecta entre ellos (1 Cor 16:1). Primera de Pedro 1:1 incluye a Galacia entre las provincias cuyos destinatarios reciben la carta. En 2 Timoteo 4:10, Crescente parte hacia Galacia (algunos manuscritos leen ''Galia'', es decir, Francia).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1054', 'spa', 'gálata, perteneciente a Galacia, relativo a la región de Galacia', 'Este adjetivo significa gálata o perteneciente a Galacia, una región en el centro de Asia Menor (la actual Turquía). El área estaba habitada por tribus celtas que emigraron allí en el siglo tercero a.C., dándole a la región su carácter distintivo. En Hechos, Lucas describe dos veces los viajes misioneros de Pablo a través de ''la región de Galacia'' o ''el país gálata'' (Hechos 16:6; 18:23). Estas referencias indican la labor evangelística de Pablo en el interior de Asia Menor, estableciendo las iglesias a las que posteriormente dirigiría su carta a los Gálatas. El adjetivo funciona geográficamente para especificar qué región atravesó Pablo durante su segundo y tercer viaje misionero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1055', 'spa', 'calma, quietud del mar, ausencia total de viento y oleaje', 'Este término describe la profunda quietud del mar cuando el viento y las olas cesan por completo. En los relatos evangélicos, después de que Jesús reprende al viento y al mar, sobreviene «una gran calma», un cese inmediato y total de la violenta tempestad. El uso clásico distingue entre la calma marítima y la calma atmosférica. Aunque el vocablo puede denotar metafóricamente serenidad de ánimo, en el Nuevo Testamento aparece únicamente en sentido literal meteorológico. La transición súbita de feroz tormenta a quietud perfecta amplifica el impacto dramático del milagro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1056', 'spa', 'Galilea, la region septentrional de Palestina donde Jesus ejercio la mayor parte de su ministerio terrenal', 'Galilaia (del hebreo ha-galil, ''el circulo'' o ''el distrito'') designa la region septentrional de Palestina donde Jesus crecio, llamo a sus primeros discipulos y realizo la mayor parte de su ministerio publico. La antigua designacion de Isaias ''Galilea de los gentiles'' (Mt 4:15, citando Is 9:1) alude al caracter etnico mixto de la region, lo cual la hizo teologicamente significativa como el lugar donde la luz resplandeció primero. Con 61 apariciones en los Evangelios y Hechos, es una de las regiones mas frecuentemente mencionadas en el Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1057', 'spa', 'Galileo — natural o habitante de la region de Galilea en el norte de Israel; gentilicio. El adjetivo Γαλιλαῖος (Galilaios) identifica a una persona de', 'Galileo — natural o habitante de la region de Galilea en el norte de Israel; gentilicio. El adjetivo Γαλιλαῖος (Galilaios) identifica a una persona de Galilea, la region nortena de Israel en torno al Mar de Galilea. Las once ocurrencias en el Nuevo Testamento funcionan como gentilicio propio que marca origen etnico-geografico. Pedro es reconocido como galileo por su acento durante el juicio de Jesus (Mateo 26:69; Marcos 14:70). Los angeles llaman a los apostoles ''varones galileos'' en la Ascension (Hechos 1:11), y los oyentes de Pentecostes se asombran de que estos hablantes sean galileos (Hechos 2:7). El espanol ''galileo'', el frances ''Galileen'' y el arabe ''jalili'' transliteran directamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1058', 'spa', 'Galión, procónsul romano de Acaya que desestimó los cargos contra Pablo en Corinto', 'Galión fue el procónsul romano de Acaya durante el ministerio de Pablo en Corinto, hacia los años 51-52 d. C. Hermano del filósofo Séneca, las fuentes extrabíblicas lo describen como un administrador culto y afable. Cuando los dirigentes judíos llevaron a Pablo ante su tribunal, Galión se negó a juzgar lo que consideraba una disputa religiosa interna, sentando en la práctica un precedente legal de que el cristianismo no era ilícito bajo la ley romana. Su actitud displicente ante la golpiza de Sóstenes sugiere indiferencia hacia los conflictos judeo-cristianos o bien una protección deliberada de la misión paulina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1059', 'spa', 'Gamaliel, un fariseo respetado y doctor de la Ley, maestro de Saulo de Tarso', 'Este nombre propio, del hebreo גַּמְלִיאֵל (Gamli''el, posiblemente ''recompensa de Dios'' o ''Dios es mi recompensa''), identifica a Gamaliel el Anciano, uno de los rabinos más honrados en la historia judía. Nieto del famoso Hillel, Gamaliel tenía el título de Rabán (''nuestro maestro'') y era miembro del Sanedrín. Hechos lo presenta como una voz de sabiduría y moderación. Aconsejó al concilio no luchar contra los apóstoles, no sea que se encuentren luchando contra Dios (Hechos 5:34). Más tarde, Pablo se identifica como habiendo sido educado ''a los pies de Gamaliel'' (Hechos 22:3), destacando sus impecables credenciales judías. Gamaliel representa lo mejor del aprendizaje y la prudencia farisaicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1060', 'spa', 'Casarse, tomar esposo/a; como participio, persona casada.', 'Casarse, tomar esposo/a; como participio, persona casada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1061', 'spa', 'Dar en matrimonio; disponer o entregar a alguien (especialmente una hija) en casamiento.', 'Variante de γαμίζω, este verbo describe el acto de dar a alguien en matrimonio, típicamente cuando un padre o tutor concerta la boda en lugar de la persona que se casa. Jesús lo emplea en el discurso escatológico: en los días de Noé, la gente ''se casaba y se daba en casamiento'' hasta que llegó el diluvio (Mt 24:38; Lc 17:27). También enseña que en la resurrección no se casan ni se dan en casamiento, sino que son como los ángeles (Mt 22:30; Mr 12:25; Lc 20:35). La voz pasiva ''ser dado en matrimonio'' refleja la realidad social antigua donde los matrimonios eran concertados por las familias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1062', 'spa', 'Boda, banquete nupcial; una celebración nupcial o la institución del matrimonio en sí.', 'Boda, banquete nupcial; una celebración nupcial o la institución del matrimonio en sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1063', 'spa', 'Pues, porque, ya que; conjunción postpositiva que da la razón, fundamento o explicación de lo precedente', 'Conjunción causal y explicativa fundamental, siempre postpositiva (nunca abre la oración). Introduce la razón, causa o evidencia de lo afirmado previamente. Se traduce ''pues'', ''porque'', ''ya que'', ''en efecto''. Es la partícula favorita de Pablo para construir cadenas de razonamiento teológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1064', 'spa', 'Vientre o entraña; la cavidad corporal interna asociada al embarazo y la concepción, o el estómago como sede del apetito.', 'γαστήρ abarca la cavidad abdominal interna, cubriendo dos usos estrechamente relacionados pero distintos: el vientre en contextos de embarazo y el estómago como órgano del apetito. La mayoría de las apariciones en el NT involucran concepción y embarazo: ''tener en el vientre'' (ἐν γαστρὶ ἔχουσα) es la expresión griega habitual para estar encinta, presente en la anunciación a María (Lc 1:31), la profecía isaiana (Mt 1:23) y las advertencias sobre las dificultades del fin de los tiempos para las embarazadas (Mt 24:19; Mr 13:17; Lc 21:23). En cambio, Tito 1:12 cita al poeta cretense Epiménides: ''Los cretenses son siempre mentirosos, malas bestias, vientres perezosos'', donde γαστήρ designa el estómago como símbolo de gula.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1065', 'spa', 'Partícula enclítica enfática: ciertamente, en verdad; al menos, por lo menos; incluso (fuerza escalar intensificadora).', 'Partícula enclítica enfática: ciertamente, en verdad; al menos, por lo menos; incluso (fuerza escalar intensificadora).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1067', 'spa', 'Gehenna — el Valle de Hinom como símbolo del castigo escatológico; infierno, lugar de destrucción final. Γέεννα, transliteración griega del hebreo gē-', 'Gehenna — el Valle de Hinom como símbolo del castigo escatológico; infierno, lugar de destrucción final. Γέεννα, transliteración griega del hebreo gē-hinnom (Valle de Hinom), transforma un topónimo específico de Jerusalén en la imagen primaria del castigo escatológico en el Nuevo Testamento. El valle al sur de Jerusalén se había hecho infame como lugar de sacrificio infantil a Moloc (2 R 23:10; Jer 7:31-32), y para el período intertestamentario simbolizaba el lugar del juicio divino sobre los impíos. Jesús emplea el término exclusivamente en los Sinópticos, advirtiendo que el cuerpo entero puede ser arrojado a la Gehenna (Mt 5:29-30), que Dios puede destruir allí tanto el alma como el cuerpo (Mt 10:28) y que su fuego es inextinguible (Mr 9:43-48). Santiago 3:6 extiende la imagen a la lengua ''encendida por la Gehenna.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1068', 'spa', 'Getsemaní, un huerto en el Monte de los Olivos donde Jesús oró antes de Su arresto', 'Este nombre de lugar, del hebreo/arameo que significa ''prensa de aceite'' o ''prensa de olivas'', identifica el huerto en el Monte de los Olivos donde Jesús se retiró a orar la noche antes de Su crucifixión. El sitio probablemente contenía una prensa de aceitunas, dándole su nombre. Aunque Juan 18:1 lo llama un ''huerto'' sin nombrarlo, Mateo y Marcos específicamente lo nombran Getsemaní (Mat 26:36; Mar 14:32). Este lugar se convirtió en el escenario de la oración angustiada de Jesús, Su aceptación de la copa del sufrimiento, y Su arresto. El nombre evoca uno de los momentos más profundos de las Escrituras: el Hijo de Dios sometiéndose a la voluntad del Padre mientras Sus discípulos dormían cerca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1069', 'spa', 'Vecino; persona que vive cerca, en la misma comunidad', 'El sustantivo γείτων designa al vecino, es decir, a alguien que vive en cercanía física. Las cuatro apariciones en el Nuevo Testamento se encuentran en Lucas y Juan, y llevan una connotación cálida de comunidad. En las instrucciones parabólicas de Jesús, se le dice al anfitrión que no invite a sus vecinos a un banquete esperando reciprocidad (Lc 14:12). El pastor que halla su oveja perdida y la mujer que encuentra su moneda perdida convocan a amigos y vecinos para compartir su alegría (Lc 15:6, 9). En Juan 9:8, los vecinos del ciego de nacimiento debaten su identidad tras la sanación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1070', 'spa', 'reír, expresar alegría o diversión mediante la risa', 'Este verbo significa reír, expresando alegría, diversión, o a veces desprecio mediante la risa. El griego clásico lo usaba en un rango desde la alegría genuina hasta la burla derisoria. En el Nuevo Testamento, Jesús lo usa en dos bienaventuranzas y ayes paralelos en el Sermón del Llano de Lucas. Pronuncia bendición sobre aquellos que lloran ahora, prometiendo ''ustedes reirán'' (Lucas 6:21), y pronuncia ay sobre aquellos que ríen ahora, advirtiendo ''ustedes lamentarán y llorarán'' (Lucas 6:25). El marcado contraste crea un tema de reversión: el dolor presente se convertirá en gozo, la risa presente en lamento. Ambos usos son futuro indicativo, prometiendo ciertas reversiones venideras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1072', 'spa', 'Llenar completamente un recipiente, vasija o espacio con una sustancia; cargar o atiborrar hasta el tope.', 'Verbo concreto y físico que significa llenar algo hasta su capacidad máxima. En los Evangelios aparece en momentos narrativos vívidos: los sirvientes llenando las tinajas de piedra con agua en Caná (Juan 2:7), los discípulos recogiendo doce canastas llenas de sobras (Juan 6:13) y las olas inundando una barca en el mar de Galilea (Marcos 4:37). Ya sea que el objeto sea una tinaja, una canasta, una barca o una esponja (Marcos 15:36), la palabra siempre evoca la imagen de algo colmado hasta el borde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1073', 'spa', 'Estar lleno, colmado de — rebosante o cargado de contenidos fisicos o cualidades morales. El verbo γέμω (gemo) significa estar lleno o rebosante de al', 'Estar lleno, colmado de — rebosante o cargado de contenidos fisicos o cualidades morales. El verbo γέμω (gemo) significa estar lleno o rebosante de algo, usado para recipientes, lugares o personas cargados de contenidos fisicos o morales. Jesus denuncia a los fariseos cuyas copas estan ''llenas de'' avaricia por dentro (Mateo 23:25) y que se asemejan a sepulcros ''llenos de'' huesos (Mateo 23:27). Pablo cita el salmo sobre bocas ''llenas de'' maldicion (Romanos 3:14). En Apocalipsis, los seres vivientes estan ''llenos de'' ojos (Apocalipsis 4:6), las copas ''llenas de'' incienso (Apocalipsis 5:8) y las copas ''llenas de'' plagas (Apocalipsis 15:7). El espanol ''lleno/llena'' y el aleman ''voll'' captan el significado de manera consistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1074', 'spa', 'generación — las personas que viven en una época determinada, o el lapso temporal de una sucesión generacional', 'generación — las personas que viven en una época determinada, o el lapso temporal de una sucesión generacional');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1076', 'spa', 'genealogía, linaje familiar, registro de descendencia, rastreo de estirpe', 'Este sustantivo denota una genealogía o registro de descendencia familiar, el rastreo de la estirpe de uno a través de líneas ancestrales. El griego clásico lo usaba para el estudio o registro de linajes. En el Nuevo Testamento, Pablo lo usa negativamente en sus epístolas pastorales, advirtiendo contra la especulación interminable sobre genealogías. Le dice a Timoteo que mande a ciertas personas no enseñar doctrinas diferentes ni ''prestar atención a fábulas y genealogías interminables que causan disputas'' (1 Tim 1:4), y luego le dice a Tito que ''evite las discusiones necias, genealogías, contiendas y disputas acerca de la ley'' (Tito 3:9). La preocupación no es con los registros genealógicos legítimos (como los de Mateo y Lucas) sino con enseñanzas especulativas y divisivas que generaban controversia sin provecho espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1077', 'spa', 'celebración de cumpleaños, fiesta de cumpleaños, aniversario del nacimiento', 'Este sustantivo plural neutro denota una celebración o fiesta de cumpleaños que conmemora el nacimiento de alguien. El griego clásico distinguía genesia (fiestas conmemorativas para los muertos) de genethlia (celebraciones de cumpleaños para los vivos), aunque las palabras podían traslaparse. En el Nuevo Testamento, ambas ocurrencias describen el mismo evento: la fiesta de cumpleaños de Herodes Antipas donde la hija de Herodías bailó y Juan el Bautista fue decapitado. Mateo registra que ''el cumpleaños de Herodes'' fue celebrado (Mat 14:6), mientras que Marcos especifica ''su cumpleaños'' cuando Herodes hizo una fiesta (Mar 6:21). Esta notoria celebración se hizo infame como la ocasión cuando un juramento precipitado llevó al martirio del precursor de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1078', 'spa', 'Origen, nacimiento, génesis; usado para linaje genealógico, el evento del nacimiento y el curso de la existencia.', 'Abarca un campo semántico que va desde el origen y el nacimiento hasta el proceso de llegar a ser. Mateo abre su Evangelio con el ''libro de la génesis'' de Jesucristo (Mt 1:1), evocando tanto el registro genealógico como una nueva creación. La misma palabra describe las circunstancias del nacimiento de Jesús (Mt 1:18). Lucas la emplea para referirse al gozo que rodea el nacimiento de Juan el Bautista (Lc 1:14). Santiago la utiliza en dos expresiones llamativas: el ''rostro de su génesis'' — la apariencia natural de uno (Stg 1:23) — y ''la rueda de la génesis'', el ciclo de la existencia incendiado por la lengua (Stg 3:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1080', 'spa', 'Engendrar (del padre), nacer (pasivo) o dar a luz (de la madre); abarca linaje fisico, renacimiento espiritual y generacion divina', 'Un verbo que se halla en el corazon de la genealogia y la teologia biblicas por igual. Solo en el primer capitulo de Mateo aparece decenas de veces trazando el linaje desde Abraham hasta Cristo: ''Abraham engendro a Isaac.'' Sin embargo, la misma palabra describe el ''nacer del Espiritu'' en Juan 3 y el ''ser nacido de Dios'' en 1 Juan, extendiendo la generacion fisica al ambito del renacimiento espiritual. Los escritores neotestamentarios llevan esta metafora mas lejos que cualquier autor clasico. El espanol distingue bien entre ''engendro'' (voz activa) y ''ha nacido'' (voz pasiva).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1081', 'spa', 'Fruto, producto o cosecha de la tierra; también descendencia o camada, usado como epíteto metafórico de reproche.', 'Sustantivo con dos aplicaciones bastante distintas. En su sentido agrícola, se refiere al fruto o producto de la tierra, especialmente en la célebre expresión «fruto de la vid» pronunciada por Jesús en la Última Cena (Mateo 26:29; Marcos 14:25; Lucas 22:18). En 2 Corintios 9:10, Pablo lo emplea para hablar de la cosecha que Dios multiplica a los que dan con generosidad. El otro sentido es marcadamente metafórico: «camada de víboras», un epíteto mordaz lanzado por Juan el Bautista y por Jesús contra la élite religiosa (Mateo 3:7; 12:34; 23:33; Lucas 3:7), subrayando la metáfora biológica de descender de una estirpe venenosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1082', 'spa', 'Genesaret, llanura fértil en la ribera noroeste del mar de Galilea', 'Genesaret designaba tanto una llanura fértil como, por extensión, el lago mismo (también llamado mar de Galilea o lago de Tiberíades). La región era célebre en la antigüedad por su productividad agrícola y su clima agradable. La llanura de la ribera noroeste ofrecía tierras de cultivo muy ricas. Cuando los Evangelios mencionan que Jesús y los discípulos desembarcaron «en Genesaret», se refieren a esta zona costera distintiva. El nombre deriva del hebreo Kinéret, posiblemente con el significado de «en forma de arpa», por el contorno del lago.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1083', 'spa', 'nacimiento, engendramiento, procreación; producción o alumbramiento', 'Sustantivo femenino que designa el proceso de traer algo a la existencia. Su referencia principal es al nacimiento biológico: el acto de engendrar o nacer. Abarca tanto la acción de procrear (desde la perspectiva del progenitor) como el evento del nacimiento mismo (desde la perspectiva del descendiente). La palabra se extiende metafóricamente a la producción de bienes u otras abstracciones, conservando el sentido fundamental de algo que es dado a luz o generado. El uso neotestamentario se centra en el significado de nacimiento, mientras que los textos clásicos lo emplean más ampliamente para cualquier tipo de producción o generación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1084', 'spa', 'nacido, engendrado, traído a la existencia por nacimiento, nacido de (mujer)', 'Este adjetivo verbal significa nacido o engendrado, describiendo a alguien traído a la existencia mediante nacimiento natural. El griego clásico lo usaba para distinguir a los naturalmente engendrados de los adoptados, y para describir a mortales (nacidos) en contraste con dioses inmortales. En el Nuevo Testamento, Jesús lo usa en dichos paralelos sobre la dignidad humana y la grandeza de Juan el Bautista. Él declara que entre ''los nacidos de mujeres'' no se ha levantado nadie más grande que Juan el Bautista (Mat 11:11), con Lucas registrando la frase idéntica (Luc 7:28). La expresión ''nacidos de mujeres'' es un modismo hebreo que significa toda la humanidad—cada persona que haya vivido entró al mundo mediante nacimiento humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1085', 'spa', 'Raza, linaje familiar, descendencia; clase o tipo de cosa; nacion etnica o grupo de personas con ascendencia comun.', 'Raza, linaje familiar, descendencia; clase o tipo de cosa; nacion etnica o grupo de personas con ascendencia comun.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1086', 'spa', 'Gerasenos, habitantes de Gerasa/Gergesa, region en la orilla oriental del mar de Galilea', 'Los gerasenos eran los habitantes de la region de Gerasa o Gergesa, situada en la orilla oriental del mar de Galilea. Las variantes textuales en los manuscritos evangelicos reflejan incertidumbre sobre la ubicacion precisa: algunos leen ''gadarenos'', otros ''gergesenos'' y otros ''gerasenos''. El sitio mas probable es Gergesa (la actual Kursi), directamente en la ribera oriental del lago, con laderas empinadas que descienden hasta el agua, lo cual coincide con los detalles topograficos del relato sobre los cerdos precipitandose por el despenadero. Era territorio predominantemente gentil, lo que explica la presencia de piaras de cerdos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1089', 'spa', 'Gustar, probar; literalmente comer o beber, figuradamente experimentar algo de primera mano, especialmente la muerte o la gracia divina.', 'Gustar, probar; literalmente comer o beber, figuradamente experimentar algo de primera mano, especialmente la muerte o la gracia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1092', 'spa', 'Labrador, agricultor arrendatario o viñador que trabaja la tierra agrícola, especialmente en las parábolas de la viña y dichos sapienciales.', 'Labrador, agricultor arrendatario o viñador que trabaja la tierra agrícola, especialmente en las parábolas de la viña y dichos sapienciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1093', 'spa', 'Tierra, terreno, suelo — el mundo entero, un territorio específico, la tierra como sustancia física, o tierra firme frente al mar', 'El griego γῆ es notablemente elástico: se extiende desde el planeta creado en su totalidad (''cielo y tierra'', Mt 5:18) hasta un país con nombre propio (''la tierra de Israel'', Mt 2:20), pasando por la tierra que trabaja el labrador (''la semilla cayó en pedregales'', Mc 4:5) y la orilla donde el pescador arrastra su barca (Lc 5:11). Solo el contexto determina la escala que se tiene a la vista. El español tierra y el francés terre reflejan esta misma amplitud, colapsando significados cósmicos, políticos, agrícolas y costeros en una sola palabra — un patrón que la evidencia multilingüe confirma como casi universal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1095', 'spa', 'envejecer, hacerse viejo, llegar a la vejez, avanzar en años', 'Este verbo significa envejecer o avanzar en edad, describiendo el proceso natural de avanzar en años y los cambios físicos que acompañan el envejecimiento. El griego clásico lo usaba tanto para personas como para cosas que se vuelven viejas u obsoletas. El Nuevo Testamento lo usa una vez literalmente y una vez metafóricamente. Jesús profetiza a Pedro que ''cuando seas viejo'' (literalmente ''cuando envejezcas'') extenderá sus manos y será llevado donde no desea—una predicción del martirio de Pedro (Juan 21:18). Hebreos lo usa metafóricamente: lo que Dios llama ''nuevo'' ha hecho antiguo al primer pacto, y lo que está envejeciendo y haciéndose viejo está listo para desaparecer (Heb 8:13). Ambos usos involucran transición hacia un final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1096', 'spa', 'Llegar a ser, suceder, acontecer, nacer, ser hecho; el verbo fundamental de transición, surgimiento y ocurrencia', 'El verbo maestro del cambio y la emergencia en griego, con un campo semántico vastísimo que abarca desde el puro acontecer hasta el nacimiento, la creación y la transformación de estado. A diferencia de εἰμί (ser estático), γίνομαι enfoca el proceso de llegar a ser, el momento de transición, el evento que irrumpe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1097', 'spa', 'Conocer, saber, comprender, percibir o enterarse; abarca el conocimiento relacional, intelectual, perceptivo y el descubrimiento', 'γινώσκω es el verbo principal del Nuevo Testamento para expresar conocimiento, con una calidez y cercanía que su pariente más intelectual οἶδα a menudo carece. Mientras οἶδα tiende al saber proposicional, γινώσκω implica conocimiento experiencial, relacional o perceptivo: se «conoce» a una persona, una verdad con la que se ha luchado, un misterio ahora revelado. Jesús «conocía sus pensamientos» (Mt 12:15), Pablo «nada sabía contra sí mismo» (1 Co 4:4), y la gran declaración joánica pide que el mundo «conozca que tú me enviaste» (Jn 17:23). El árabe distribuye el campo semántico entre عَرَفَ (familiaridad), فَهِمَ (comprensión) y عُلِمَ (ser conocido en voz pasiva), iluminando distinciones que el griego concentra en un solo verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1099', 'spa', 'Dulce, fresco (referido al sabor o al agua); agradable, placentero', 'En el griego clásico, γλυκύς describía todo lo dulce al gusto o al olfato y se extendía figuradamente a lo agradable o querido. El Nuevo Testamento lo emplea exclusivamente en su sentido literal. Santiago contrasta el agua dulce y la amarga que brotan de un mismo manantial como metáfora del hablar incoherente (Stg 3:11-12), mientras que Apocalipsis describe el librito que sabe dulce como la miel en la boca pero se vuelve amargo en el estómago (Ap 10:9-10). El término captura esa cualidad sensorial básica de dulzura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1100', 'spa', 'La lengua como organo fisico; por extension, hablar en lenguas como don del Espiritu en forma de expresion extatica o en idiomas desconocidos', 'En su sentido mas basico, esta palabra designa la lengua fisica en la boca, el organo del gusto y del habla. Los Evangelios la emplean en relatos de sanacion donde Jesus desata una lengua trabada (Mc 7:33, 35) o la lengua de Zacarias queda libre para alabar a Dios (Lc 1:64). El espanol ''lengua'' porta tanto el significado fisico como el lingüistico, reflejando el rango semantico del griego. El desarrollo distintivo del Nuevo Testamento es el ''hablar en lenguas,'' el don carismatico de expresion por el Espiritu en idiomas no aprendidos o habla extatica, prominente en Pentecostes (Hch 2:3-4) y a lo largo de la discusion paulina sobre los dones espirituales (1 Co 12-14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1101', 'spa', 'caja de dinero, caja de caudales, cofre o bolsa pequeña para guardar dinero o valores', 'Este sustantivo originalmente denotaba un estuche para guardar las boquillas de instrumentos de viento, pero llegó a significar una caja o bolsa pequeña para dinero y objetos de valor. El significado clásico relacionado incluye un ataúd o sarcófago (otro tipo de caja), mostrando el sentido básico de la palabra como un contenedor. En el Nuevo Testamento, aparece dos veces en el Evangelio de Juan, ambas veces describiendo la caja de dinero que Judas llevaba para Jesús y los discípulos. Juan nota que ''Judas tenía la bolsa del dinero'' y era un ladrón que tomaba de lo que se ponía en ella (Juan 12:6), y luego que Judas tenía a su cargo la bolsa del dinero cuando Jesús le dijo que comprara lo necesario para la fiesta (Juan 13:29).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1103', 'spa', 'Genuino, verdadero, legítimo; auténtico en relación o carácter', 'Derivado de γένος (linaje, estirpe), γνήσιος significaba originalmente ''nacido legítimamente'' y pasó a denotar todo lo auténtico o sincero. Pablo lo emplea para poner a prueba la autenticidad del amor de los corintios (2 Cor 8:8), se dirige a un colaborador de confianza como ''verdadero compañero de yugo'' (Fil 4:3) y llama a Timoteo y a Tito sus ''verdaderos hijos'' en la fe (1 Tim 1:2; Tit 1:4). La palabra transmite calidez junto con su reclamo de autenticidad, afirmando vínculos que son reales y no meramente formales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1106', 'spa', 'Opinión meditada, juicio o consejo; también propósito firme, resolución o intención determinada.', 'Derivado del verbo griego que significa conocer (γιγνώσκω), este sustantivo conlleva el peso del pensamiento reflexivo, ya sea expresado como consejo o cristalizado en una resolución firme. Pablo lo emplea para ofrecer su opinión personal en asuntos donde no tiene mandato directo del Señor, como el matrimonio y la virginidad (1 Corintios 7:25, 40), y apela a la unidad de parecer (γνώμη) en la iglesia de Corinto (1 Corintios 1:10). En Apocalipsis, el término se desplaza hacia un propósito inquebrantable: los diez reyes comparten «un mismo propósito» al entregar su poder a la bestia, y Dios mismo ha puesto en sus corazones ejecutar su designio (Apocalipsis 17:13, 17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1107', 'spa', 'Dar a conocer, revelar, declarar; ser dado a conocer; llegar a saber.', 'Dar a conocer, revelar, declarar; ser dado a conocer; llegar a saber.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1108', 'spa', 'Conocimiento: comprension cognitiva y discernimiento espiritual, especialmente el conocimiento de Dios y la verdad divina.', 'Conocimiento: comprension cognitiva y discernimiento espiritual, especialmente el conocimiento de Dios y la verdad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1110', 'spa', 'Conocido, notable, reconocido; como sustantivo, un conocido o allegado familiar.', 'Conocido, notable, reconocido; como sustantivo, un conocido o allegado familiar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1111', 'spa', 'Murmurar, refunfuñar o quejarse en voz baja; expresar descontento mediante quejas susurradas contra una persona o situación.', 'Verbo que capta el rumor sordo del descontento colectivo: ese tipo de queja entre dientes que se propaga por una multitud. En los Evangelios aparece cuando los fariseos murmuran contra Jesús por comer con pecadores (Lucas 5:30), cuando la muchedumbre protesta porque Jesús declara su origen celestial (Juan 6:41, 43, 61) y cuando los jornaleros se quejan del pago desigual (Mateo 20:11). Pablo advierte a los corintios que no murmuren como lo hizo Israel en el desierto (1 Corintios 10:10). El español «murmurar» conserva la misma cualidad onomatopéyica del griego, donde los sonidos repetidos de gamma imitan el zumbido del descontento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1112', 'spa', 'murmuración, queja en voz baja; descontento susurrado entre la multitud', 'Γογγυσμός designa el murmullo descontento y en voz baja, ese tipo de queja que circula entre la gente sin expresarse abiertamente. En Juan 7:12 describe los cuchicheos divididos sobre Jesús entre las multitudes durante la fiesta. Hechos 6:1 registra la murmuración de los helenistas contra los hebreos por la distribución diaria de alimentos. Pablo exhorta a los filipenses a hacerlo todo sin murmuraciones (Fil 2:14), y Pedro insta a la hospitalidad sin quejas (1 Pe 4:9). El término apunta consistentemente al descontento comunitario expresado en voz baja.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1115', 'spa', 'Golgota, el lugar de la calavera, sitio de la crucifixion de Jesus fuera de Jerusalen', 'Golgota es el nombre arameo (גָּלְגָּלְתָּא) del lugar donde Jesus fue crucificado, que significa ''calavera'' o ''lugar de la calavera''. Los cuatro Evangelios identifican esta ubicacion; los sinopticos proporcionan el nombre arameo junto con su traduccion griega (κρανίον, de donde deriva el latin ''Calvario''). La ubicacion precisa sigue siendo debatida: la Iglesia del Santo Sepulcro y el Calvario de Gordon son los principales sitios propuestos. El nombre podria derivar de la apariencia de calavera del afloramiento rocoso o de su asociacion con las ejecuciones. Se encontraba fuera de las murallas de la ciudad, como lo exigia la ley para los lugares de ejecucion ritualmente impuros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1116', 'spa', 'Gomorra; una de las ciudades de la llanura destruida por juicio divino, sinónimo de maldad extrema.', 'Nombre propio de una de las ciudades de la llanura del Jordán destruida junto con Sodoma por fuego y azufre (Gn 19). En el NT funciona casi exclusivamente como arquetipo de juicio divino catastrófico. Jesús invoca a Sodoma y Gomorra para advertir a las ciudades inhospitalarias que su suerte será peor (Mt 10:15; Mr 6:11). Pablo cita la referencia de Isaías a Gomorra respecto a la casi total destrucción de Israel (Ro 9:29). Tanto Pedro como Judas señalan su destrucción como ejemplo de advertencia para los impíos (2 P 2:6; Jud 1:7). El nombre se transliterada de forma consistente como ''Gomorra'' en español.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1117', 'spa', 'Carga, cargamento, mercancias transportadas por barco o bestia de carga', 'Este termino designa la carga o el cargamento: mercancias transportadas por barco o sobre animales de carga. El uso clasico abarca tanto la carga maritima como los fardos de camellos. En Hechos, el barco de Pablo transporta un cargamento de trigo. En Apocalipsis, la ''carga'' representa los diversos articulos de lujo comerciados por los mercaderes que lamentan la caida de Babilonia. El termino subraya la dimension comercial de las antiguas redes de intercambio, donde navios y caravanas trasladaban desde granos basicos hasta articulos exoticos a traves del Mediterraneo y el Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1118', 'spa', 'Padre(s), progenitor(es); casi siempre en plural en el NT para designar a ambos padres juntos.', 'Padre(s), progenitor(es); casi siempre en plural en el NT para designar a ambos padres juntos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1119', 'spa', 'Rodilla — la articulación de la pierna; usada literalmente y en la expresión de arrodillarse en adoración, oración o sumisión. El sustantivo γόνυ desi', 'Rodilla — la articulación de la pierna; usada literalmente y en la expresión de arrodillarse en adoración, oración o sumisión. El sustantivo γόνυ designa la rodilla como parte del cuerpo, pero casi todas las apariciones neotestamentarias conllevan la carga adicional de adoración, oración o sumisión. ''Doblar la rodilla'' (τιθέναι τὰ γόνατα o κάμπτειν γόνυ) es la postura de súplica ante Jesús (Mr 1:40; 10:17; Lc 5:8), de oración ferviente (Lc 22:41; Hch 7:60; 9:40; 20:36; 21:5) y de adoración escatológica cuando toda rodilla se doblará ante el nombre de Jesús (Ro 11:4; 14:11; Fil 2:10; Ef 3:14). Las rodillas débiles o vacilantes de Hebreos 12:12 aluden a Isaías 35:3, exhortando a la perseverancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1120', 'spa', 'caer de rodillas, arrodillarse (ante alguien) en súplica, reverencia o burla', 'Γονυπετέω combina γόνυ (rodilla) y πίπτω (caer), describiendo vívidamente el acto de dejarse caer de rodillas. En los Evangelios aparece en momentos de súplica urgente o acercamiento reverente. Un padre se arrodilla ante Jesús rogando la sanidad de su hijo epiléptico (Mat 17:14), un leproso implora purificación (Mar 1:40), un hombre rico busca la vida eterna (Mar 10:17), y los soldados se arrodillan burlonamente durante la Pasión (Mat 27:29). El gesto transmite tanto la petición desesperada como, cuando se pervierte, la cruel burla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1121', 'spa', 'Letra del alfabeto, documento escrito, las Escrituras, la ley escrita (frente al Espíritu), erudición o correspondencia.', 'Letra del alfabeto, documento escrito, las Escrituras, la ley escrita (frente al Espíritu), erudición o correspondencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1122', 'spa', 'Escriba, experto en la Ley mosaica y la tradicion judia; tambien secretario o funcionario municipal', 'En el Nuevo Testamento, el γραμματεύς es casi siempre un escriba judio: un erudito profesional formado en la copia, interpretacion y ensenanza de la Tora. Estos escribas aparecen regularmente junto a fariseos y sumos sacerdotes como el estamento religioso que cuestiona, pone a prueba y finalmente se opone a Jesus. Preguntan por que come con pecadores (Mc 2:16), desafian su autoridad (Mc 11:27-28) y participan en su juicio y condena. En un pasaje excepcional, la misma palabra designa al secretario municipal de Efeso que apaciguo el motin provocado por Demetrio el platero (Hch 19:35), reflejando el sentido griego mas amplio de ''secretario'' o ''registrador.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1124', 'spa', 'Escritura o las Escrituras; los escritos sagrados autoritativos, referidos a la Biblia hebrea y a textos apostolicos', 'Derivada de γράφω (''escribir''), γραφή en el Nuevo Testamento designa casi exclusivamente los escritos sagrados reconocidos como divinamente autoritativos. Jesus apela a ella en debates: ''¿No habeis leido esta Escritura?'' (Mc 12:10), y declara que ''la Escritura no puede ser quebrantada'' (Jn 10:35). Tras la resurreccion, abre el entendimiento de los discipulos ''para que comprendiesen las Escrituras'' (Lc 24:32, 45). Pablo fundamenta su evangelio en ella: Cristo murio y resucito ''conforme a las Escrituras'' (1 Co 15:3-4), y ''toda la Escritura es inspirada por Dios'' (2 Ti 3:16). El singular suele senalar un pasaje concreto, mientras que el plural αἱ γραφαί abarca todo el canon hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1125', 'spa', 'Escribir, componer o inscribir; de redactar documentos, citar las Escrituras con «escrito está» y registrar en textos o libros', 'γράφω es el verbo griego estándar para el acto de escribir, pero en el Nuevo Testamento adquiere un peso teológico singular. Cuando Jesús responde a Satanás con «escrito está» (γέγραπται, Mt 4:4, 7, 10), el tiempo perfecto no señala mera inscripción pasada sino autoridad vigente: lo que fue escrito sigue en pie. Esta fórmula de citación representa aproximadamente un tercio de todas las ocurrencias neotestamentarias y es notablemente uniforme en las traducciones: español «Escrito está», francés «il est écrit», alemán «es steht geschrieben», todos preservan el aspecto perfectivo y el tono reverencial. Más allá de esta fórmula, γράφω cubre la redacción epistolar (las cartas de Pablo), la inscripción legal (el letrero de la cruz, Mt 27:37) e incluso la hipérbole cósmica de Jn 21:25.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1127', 'spa', 'Velar, estar alerta; principalmente vigilancia espiritual y disposicion escatologica, ocasionalmente vigilia literal.', 'Velar, estar alerta; principalmente vigilancia espiritual y disposicion escatologica, ocasionalmente vigilia literal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1128', 'spa', 'entrenar, ejercitar, disciplinar (el cuerpo o el alma mediante práctica rigurosa)', 'Derivado de γυμνός (desnudo), γυμνάζω se refería originalmente al entrenamiento atlético que se realizaba desnudo en los gimnasios griegos. El Nuevo Testamento traslada esta imagen a la formación espiritual y moral. Pablo exhorta a Timoteo a ejercitarse en la piedad más que en el mero ejercicio corporal (1 Tim 4:7). Hebreos describe a creyentes maduros cuyas facultades han sido entrenadas por la práctica para discernir el bien del mal (Heb 5:14), y una disciplina que produce fruto apacible de justicia para quienes son ejercitados por ella (Heb 12:11). Segunda Pedro advierte sobre corazones entrenados en la avaricia (2 Pe 2:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1131', 'spa', 'Desnudo, sin ropa, descubierto; abarca desde la desnudez completa hasta estar mal vestido o insuficientemente cubierto. Γυμνός cubre un espectro que v', 'Desnudo, sin ropa, descubierto; abarca desde la desnudez completa hasta estar mal vestido o insuficientemente cubierto. Γυμνός cubre un espectro que va de la desnudez total a simplemente estar mal vestido o expuesto. En la parábola de las ovejas y los cabritos, los ''desnudos'' a quienes los justos visten son quienes carecen de vestimenta adecuada (Mt 25:36-44), mientras que en Marcos 14:51-52 un joven huye literalmente desnudo de Getsemaní. Pablo emplea la palabra metafóricamente para el estado desvestido del alma sin su morada celestial (2 Co 5:3). El rango de lo físico a lo metafórico refleja el uso del griego clásico, donde γυμνός podía significar desde ''despojado de armadura'' hasta ''ligeramente vestido.'' Las dimensiones figurativas siguen siendo vitales para interpretar pasajes como Hebreos 4:13 y Apocalipsis 3:17.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1132', 'spa', 'Desnudez, estado de estar sin ropa o con ropa insuficiente, vulnerabilidad y verguenza', 'La desnudez no representa meramente la ausencia de vestimenta, sino un estado de vulnerabilidad, exposicion y, con frecuencia, verguenza. En contextos biblicos, la desnudez simboliza a menudo pobreza, degradacion o aridez espiritual. El catalogo paulino de padecimientos incluye la ''desnudez'' junto al hambre y el peligro, describiendo tanto la carencia literal de ropa adecuada como la vergonzosa vulnerabilidad de sus sufrimientos apostolicos. La advertencia de Apocalipsis a Laodicea habla de una desnudez espiritual que requiere las ''vestiduras blancas'' de la justicia para cubrir su condicion vergonzosa. El termino evoca tanto la privacion fisica como la exposicion moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1135', 'spa', 'Mujer, persona adulta femenina; esposa o cónyuge en contextos matrimoniales. γυνή abarca tanto la identidad de género como el vínculo conyugal', 'γυνή es la palabra griega estándar para una mujer adulta, empleada tanto como término general como vocablo habitual para «esposa». Jesús se dirige a su madre y a otras mujeres con el respetuoso vocativo γύναι (Jn 2:4; 19:26), y Pablo lo usa extensamente para las esposas en su enseñanza sobre el matrimonio (1 Co 7; Ef 5). La mayoría de las lenguas modernas — español «mujer», francés «femme», alemán «Frau» — reflejan la misma ambigüedad, usando una sola palabra para «mujer» y «esposa», donde el contexto determina el significado. Las 219 ocurrencias neotestamentarias abarcan relatos de sanación, parábolas, genealogías y códigos domésticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1137', 'spa', 'Esquina o ángulo de un edificio, calle o región; usado arquitectónicamente de la piedra angular y espacialmente de las esquinas de las calles.', 'Designa una esquina o ángulo, ya sea de un edificio, un cruce de calles o un sector geográfico. Su uso teológicamente más significativo se encuentra en los pasajes de la «cabeza del ángulo» (κεφαλὴ γωνίας), donde Jesús aplica el Salmo 118:22 a sí mismo como la piedra rechazada que se convierte en piedra angular (Mateo 21:42; Marcos 12:10; Lucas 20:17; Hechos 4:11; 1 Pedro 2:7). En Mateo 6:5, describe las esquinas de las calles donde los hipócritas oran para ser vistos. El español «esquina» abarca adecuadamente tanto el sentido arquitectónico como el espacial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1138', 'spa', 'David — rey de Israel, ancestro del Mesias, salmista; usado en titulos como ''Hijo de David'' y ''Llave de David''', 'Δαυείδ (tambien escrito Δαβίδ en el Texto Recibido) es la forma griega indeclinable del hebreo David, el rey paradigmatico de Israel. El nombre satura el Nuevo Testamento en multiples registros: como figura historica en genealogias (Mt 1:6, 17), como autor de los Salmos citados por Jesus y los apostoles (Mc 12:36; Hch 2:25; Heb 4:7), y sobre todo como el ancestro cuyo trono y linaje definen la expectativa mesianica. El titulo ''Hijo de David'' se convierte en una designacion cristologica primordial (Mt 1:1; 9:27; 20:30-31), mientras que ''la llave de David'' (Ap 3:7) y ''la raiz de David'' (Ap 5:5; 22:16) extienden el nombre hacia la imagineria apocaliptica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1139', 'spa', 'Estar endemoniado — estar bajo el control o la aflicción de un espíritu maligno. Δαιμονίζομαι es un verbo en voz media/pasiva que significa estar bajo', 'Estar endemoniado — estar bajo el control o la aflicción de un espíritu maligno. Δαιμονίζομαι es un verbo en voz media/pasiva que significa estar bajo el poder de un δαιμόνιον (demonio). Sus 13 apariciones neotestamentarias describen personas afligidas por fuerzas demoníacas, y todas se encuentran en los Evangelios, nunca en las Epístolas ni en Apocalipsis. Los Sinópticos lo emplean en resúmenes del ministerio sanador de Jesús (Mt 4:24; 8:16; Mr 1:32) y en relatos específicos de exorcismo (Mt 8:28-33; 9:32; 12:22; 15:22; Mr 5:15-18; Lc 8:36). Juan 10:21 recoge la acusación de los adversarios de que Jesús mismo estaba endemoniado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1140', 'spa', 'Espiritu sobrenatural; generalmente un demonio maligno que aflige a las personas, ocasionalmente una deidad pagana', 'En el Nuevo Testamento, este sustantivo neutro se refiere abrumadoramente a espiritus malevolentes que atormentan, poseen o afligen a las personas: los ''espiritus inmundos'' que Jesus y los apostoles expulsan en dramaticos encuentros a lo largo de los Evangelios (Mt 9:33; Mc 5:12; Lc 8:30). El espanol lo traduce consistentemente como ''demonios,'' apuntando al mismo concepto central. Una excepcion notable ocurre en Hechos 17:18, donde los filosofos atenienses acusan a Pablo de proclamar ''divinidades extranjeras''; aqui la palabra retiene su sentido griego clasico mas antiguo de un ser o poder divino, como bien distingue el espanol ''divinidades'' frente al habitual ''demonios.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1144', 'spa', 'Lágrima o lágrimas derramadas al llorar, expresión de dolor, compasión o súplica ferviente. Se refiere a las lágrimas físicas como señal externa de em', 'Lágrima o lágrimas derramadas al llorar, expresión de dolor, compasión o súplica ferviente. Se refiere a las lágrimas físicas como señal externa de emociones profundas: aflicción, angustia pastoral, devoción penitente u oración compasiva. Pablo invoca sus propias lágrimas para autenticar su sinceridad pastoral (Hechos 20:19, 31; 2 Corintios 2:4; 2 Timoteo 1:4). Las lágrimas de la mujer pecadora a los pies de Jesús se convierten en vehículo de adoración y arrepentimiento (Lucas 7:38, 44). Hebreos 5:7 atribuye lágrimas al propio Jesús en sus oraciones. La promesa escatológica de que Dios enjugará toda lágrima (Apocalipsis 7:17; 21:4) convierte esta palabra en un puente entre el dolor presente y el consuelo futuro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1147', 'spa', 'Dedo; dígito de la mano humana, usado literalmente para el contacto físico y figuradamente para el poder divino (''el dedo de Dios'').', 'La palabra básica para designar un dedo humano, que aparece tanto en contextos físicos cotidianos como en ricas metáforas teológicas. Jesús usa los dedos para sanar, introduciéndolos en los oídos de un sordo (Marcos 7:33), y desafía a los fariseos que imponen cargas sobre otros sin mover un dedo para ayudar (Mateo 23:4; Lucas 11:46). La expresión más llamativa es ''el dedo de Dios'' (Lucas 11:20), donde los exorcismos de Cristo se atribuyen al poder divino, evocando Éxodo 8:19. Incluso en la parábola de Lázaro, el rico suplica por una gota de agua en la punta del dedo (Lucas 16:24). La palabra posee un peso que trasciende con creces su simple referencia anatómica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1150', 'spa', 'domar, someter, poner bajo control (animales o la lengua)', 'Δαμάζω significa someter o domar lo que es salvaje e indómito. Marcos 5:4 lo emplea para describir al endemoniado gadareno a quien nadie podía sujetar; ni siquiera las cadenas lograban ''domarlo''. Santiago usa la palabra tres veces en su discurso sobre la lengua: toda especie de bestia y ave ha sido domada por el ser humano (Stg 3:7), pero ningún ser humano puede domar la lengua (Stg 3:8). El contraste entre el dominio de la humanidad sobre la naturaleza y su impotencia ante su propia habla constituye uno de los argumentos más impactantes de Santiago.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1154', 'spa', 'Damasco; la antigua capital siria, prominente en el relato de la conversión de Pablo. Δαμασκός es la forma griega del hebreo Dammeseq, una de las ciud', 'Damasco; la antigua capital siria, prominente en el relato de la conversión de Pablo. Δαμασκός es la forma griega del hebreo Dammeseq, una de las ciudades más antiguas continuamente habitadas del mundo. En el Nuevo Testamento aparece casi exclusivamente en relación con la dramática conversión y el ministerio inicial de Pablo. Fue en el camino a Damasco donde Saulo encontró al Cristo resucitado (Hch 9:3; 22:6; 26:12), y fue en Damasco donde predicó por primera vez y luego escapó descolgándose por la muralla en un canasto (Hch 9:19-25; 2 Co 11:32-33). Pablo también menciona su regreso allí tras su estancia en Arabia (Gá 1:17). La ciudad sirve así como marcador geográfico fundamental en la narrativa del apóstol más influyente del cristianismo primitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1155', 'spa', 'prestar (dinero); (voz media) pedir prestado', 'Δανείζω en voz activa significa prestar, y en voz media pedir prestado. Jesús emplea este término en el Sermón del Monte y en el Sermón del Llano para desafiar la generosidad meramente transaccional. En Mateo 5:42 ordena dar al que pide y no rechazar al que quiere pedir prestado. En Lucas 6:34-35 va más allá: incluso los pecadores prestan a pecadores esperando recibir lo mismo, pero los discípulos deben prestar sin esperar nada a cambio. La palabra se sitúa en la intersección entre la economía y la ética, redefiniendo el sentido de la generosidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1158', 'spa', 'Daniel (nombre propio): el profeta del Antiguo Testamento al que Jesús hace referencia en el discurso escatológico', 'El nombre Daniel se refiere al célebre profeta del Antiguo Testamento cuyas visiones aparecen en el libro que lleva su nombre. Jesús menciona a ''Daniel el profeta'' al hablar de las señales del fin de los tiempos, dirigiendo a su audiencia a los escritos proféticos sobre la abominación desoladora. El nombre hebreo significa ''Dios es mi Juez'', reflejando la fidelidad de Daniel durante el cautiverio babilónico. Ambas referencias en los Evangelios dirigen a los lectores a las visiones apocalípticas de Daniel como trasfondo esencial para comprender la enseñanza escatológica de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1159', 'spa', 'Gastar, expender; de dinero, recursos o de uno mismo, con matices de derroche o sacrificio generoso.', 'Verbo de gasto económico cuyo espectro va desde el desembolso neutro hasta el derroche negativo y la entrega sacrificial positiva. La mujer con hemorragia ''gastó todo lo que tenía'' en médicos sin resultado (Mr 5:26). El hijo pródigo ''gastó todo'' en una vida disoluta (Lc 15:14). Pablo instruye a los creyentes rumbo a Jerusalén que paguen los gastos del voto nazareo de cuatro hombres (Hch 21:24). De manera notable, Pablo declara que ''con mucho gusto gastaré y me desgastaré'' por las almas de los corintios (2 Co 12:15). Santiago advierte que los deseos egoístas llevan a gastar en placeres (Stg 4:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1161', 'spa', 'Pero, y, ahora; conjunción adversativa leve o de transición, más suave que ἀλλά, que marca continuación con ligero contraste', 'Pero, y, ahora — una conjunción adversativa suave o de transición, más ligera que ἀλλά, que indica continuación con un leve contraste.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1162', 'spa', 'Oración ferviente, súplica o ruego; también una petición o solicitud específica dirigida a Dios o a otros.', 'Oración ferviente, súplica o ruego; también una petición o solicitud específica dirigida a Dios o a otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1163', 'spa', 'Es necesario, se debe; expresa necesidad divina, compulsión lógica u obligación moral; también lo que es propio o conveniente', 'Pocas palabras griegas cargan tanto peso teológico en tan pocas letras. δεῖ es un verbo impersonal que declara que algo debe ser así, y en los Evangelios ese «debe» frecuentemente señala el plan divino. Jesús repite que el Hijo del Hombre «debe» padecer, morir y resucitar (Mt 16:21; Mr 8:31; Lc 9:22), y los acontecimientos apocalípticos «deben» ocurrir antes del fin (Mt 24:6). Las traducciones revelan con claridad la fuerza modal: francés «il faut», español «es necesario», alemán «muss», todas captan la compulsión impersonal. En contados casos la fuerza se atenúa de estricta necesidad a conveniencia: lo que «conviene» o es «apropiado» (1 Ti 5:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1165', 'spa', 'hacer un espectáculo público, exponer a vergüenza o desprecio; exhibir abiertamente como ejemplo', 'Este verbo conlleva el sentido de poner a alguien en exhibición pública, particularmente de manera vergonzosa o deshonrosa. José consideró divorciarse de María en secreto para evitar hacerla un ejemplo público (Mateo 1:19), mostrando la conexión del término con la humillación pública. Pablo lo usa dramáticamente en Colosenses 2:15 para describir la exhibición triunfante de Cristo de los poderes espirituales derrotados—desarmándolos y exhibiéndolos abiertamente. El término evoca la imagen de una procesión victoriosa donde se exhiben los cautivos, aunque su rango semántico incluye tanto hacer un ejemplo de alguien como hacer una demostración pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1166', 'spa', 'mostrar, exhibir, revelar — hacer que alguien vea algo, ya sea señalando un objeto físico o revelando una verdad', 'mostrar, exhibir, revelar — hacer que alguien vea algo, ya sea señalando un objeto físico o revelando una verdad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1169', 'spa', 'cobarde, temeroso, tímido; que carece de valentía o reverencia ante lo que exige fe', 'δειλός describe una disposición de cobardía o temor: el fracaso del ánimo ante el peligro o lo divino. Jesús reprende a sus discípulos como δειλοί cuando se aterran durante la tempestad en el mar de Galilea (Mt 8:26; Mr 4:40), cuestionando por qué carecen de fe. En Hebreos 12:28, el sentido afín de reverencia sobrecogedora aparece en el contexto del culto. De modo aún más contundente, Apocalipsis 21:8 sitúa a los cobardes en primer lugar entre los condenados al lago de fuego, junto con homicidas e idólatras, una advertencia solemne contra la timidez carente de fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1171', 'spa', 'terriblemente, ferozmente; expresando intensidad severa de sufrimiento o emoción', 'Este adverbio intensifica las descripciones de condiciones o emociones severas, enfatizando la naturaleza extrema de lo que se describe. En Mateo 8:6, el siervo del centurión está ''terriblemente atormentado'' por la parálisis, mientras que Lucas 11:53 describe a los escribas y fariseos volviéndose ''ferozmente hostiles'' hacia Jesús. La palabra deriva de raíces que significan ''temible'' o ''terrible'', y en el uso del Nuevo Testamento funciona para intensificar el sentido del lector de severidad—ya sea sufrimiento físico o intensidad emocional. La evidencia multilingüe (español ''terriblemente,'' francés ''terriblement'') refleja consistentemente esta función intensificadora en ambos contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1172', 'spa', 'cenar, tomar la comida principal de la tarde; compartir la mesa en sentido de comunión', 'δειπνέω se refiere a tomar la comida principal del día, generalmente la cena vespertina. En Lucas 17:8, un siervo recibe la orden de preparar la cena de su amo antes de comer él mismo. La expresión «después de haber cenado» (Lc 22:20; 1 Co 11:25) ancla la institución de la Cena del Señor en el marco de una comida real: la copa se toma μετὰ τὸ δειπνῆσαι. En Apocalipsis 3:20, Cristo promete entrar y cenar con todo aquel que le abra la puerta, una imagen de íntima comunión de mesa que resonó profundamente en la iglesia primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1173', 'spa', 'Cena, comida principal, banquete; la comida principal del día, especialmente una cena con significado comunitario o ceremonial.', 'Cena, comida principal, banquete; la comida principal del día, especialmente una cena con significado comunitario o ceremonial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1176', 'spa', 'Diez: el numero cardinal, usado en parabolas, simbolismo apocaliptico y conteo narrativo.', 'Diez: el numero cardinal, usado en parabolas, simbolismo apocaliptico y conteo narrativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1177', 'spa', 'doce, el número 12 en todos los géneros y casos gramaticales', 'El número cardinal doce, utilizado en todos los géneros a lo largo de la literatura griega desde Homero en adelante. Como numeral básico, aparece en diversas formas dialectales pero mantiene siempre el mismo significado esencial. El número tuvo una importancia especial en el contexto bíblico: las doce tribus de Israel, los doce apóstoles, las doce puertas de la Nueva Jerusalén. Funciona como numeral indeclinable o declinado según el contexto gramatical, concordando con el sustantivo que modifica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1178', 'spa', 'Quince, el numero cardinal 15', 'Un termino numerico sencillo que indica la cantidad quince. En el uso biblico, aparece para medir distancias, contar dias y senalar periodos de tiempo. Betania estaba a quince estadios de Jerusalen, aproximadamente tres kilometros, la distancia de un camino de sabado. Los marineros que sondeaban la profundidad hallaron quince brazas. Pablo paso quince dias con Pedro en Jerusalen. Estas referencias demuestran la funcion puramente cuantitativa del termino, sin connotaciones simbolicas destacadas, aunque en la numerologia judia el quince podia representarse con yod-he (parte del nombre divino) en lugar de la combinacion habitual de letras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1179', 'spa', 'Decápolis, región de diez ciudades al este y sureste del Mar de Galilea', 'La Decápolis era una liga de diez ciudades predominantemente griegas, ubicadas principalmente al este del río Jordán y del Mar de Galilea. Estas ciudades helenísticas gozaban de cierta autonomía bajo supervisión romana y representaban la cultura griega y la religión pagana en medio del territorio judío. El ministerio de Jesús se extendió ocasionalmente a esta región gentil; tras la sanidad del endemoniado gadareno, este proclamó a Jesús por toda la Decápolis. La región servía como zona de transición entre el corazón judío y el mundo gentil más amplio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1180', 'spa', 'Catorce; el número cardinal usado en la genealogía de Mateo y en las referencias cronológicas de Pablo.', 'El número cardinal catorce, que aparece exclusivamente en contextos cronológicos estructurados. Mateo organiza la genealogía de Jesús en tres grupos de catorce generaciones (Mt 1:17), una disposición teológicamente significativa dado que catorce es el valor numérico del nombre de David en hebreo (דָּוִד, dalet-waw-dalet = 4+6+4). Pablo lo emplea para señalar el lapso de catorce años desde una experiencia visionaria (2 Co 12:2) y catorce años antes de su consulta con los apóstoles de Jerusalén (Gá 2:1). La palabra griega δεκατέσσαρες corresponde directamente al español ''catorce''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1181', 'spa', 'décimo; (como sustantivo) diezmo, la décima parte entregada como ofrenda', 'δέκατος significa «décimo» y, como sustantivo (δεκάτη), designa la décima parte o diezmo. Las cuatro apariciones en el Nuevo Testamento se hallan en Hebreos 7, donde el autor argumenta la superioridad del sacerdocio de Melquisedec sobre el orden levítico. Abraham entregó el diezmo de los despojos a Melquisedec (He 7:2, 4), los levitas reciben diezmos pero ellos mismos fueron «diezmados» a través de Abraham (He 7:9), y quienes reciben los diezmos son mortales mientras que de Melquisedec se atestigua que vive (He 7:8). Así, el diezmo se convierte en instrumento de argumentación sobre el orden sacerdotal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1182', 'spa', 'Décimo, número ordinal en secuencia o una décima parte como fracción', 'Este número ordinal indica posición en una secuencia (el décimo elemento) o proporción (una décima parte, diezmo). En el Evangelio de Juan señala la «hora décima» del día en que Andrés y otro discípulo siguieron a Jesús. En Apocalipsis describe la «décima parte» de la ciudad que cayó en el terremoto y la décima piedra del cimiento de la Nueva Jerusalén. Aunque el término puede tener peso teológico al referirse al diezmo, ese sentido no aparece en estas ocurrencias neotestamentarias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1183', 'spa', 'cobrar diezmos de alguien; ser sujeto a diezmar (voz pasiva)', 'Este verbo se refiere específicamente a la práctica de cobrar o pagar diezmos—la ofrenda del diez por ciento prescrita en la ley mosaica. Hebreos 7 lo usa dos veces al discutir la superioridad de Melquisedec sobre el sacerdocio levítico: una vez para Melquisedec cobrando diezmos de Abraham (7:6), y otra en la notable declaración de que Leví mismo ''fue diezmado'' a través de Abraham (7:9). La voz pasiva en la segunda instancia crea un punto teológico sobre representación y superioridad. El término aparece exclusivamente en este pasaje de Hebreos, donde el autor construye un argumento sofisticado sobre los órdenes sacerdotales mediante un análisis cuidadoso del encuentro en Génesis 14.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1184', 'spa', 'Aceptable, grato, agradable; lo que es recibido con favor por Dios o por las personas.', 'Adjetivo que transmite la idea de ser aceptado o bien recibido, frecuentemente en el contexto del favor divino. Jesús lee en Isaías sobre ''el año agradable del Señor'' (Lc 4:19) — el año de la acogida misericordiosa de Dios — y luego declara provocadoramente que ningún profeta es ''aceptable'' en su propia tierra (Lc 4:24). Pedro descubre que todo aquel que teme a Dios le es ''grato'', sin importar su nacionalidad (Hch 10:35). Pablo cita a Isaías sobre ''el tiempo aceptable'' de la salvación (2 Co 6:2). La ofrenda de los filipenses se describe como ''aceptable'' y agradable a Dios (Fil 4:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1185', 'spa', 'Seducir, atraer con engaño hacia el pecado o el error, como quien pone cebo en una trampa', 'Este verbo describía originalmente la acción de pescar o cazar con cebo, atrayendo a la presa hacia una trampa mediante medios atractivos pero engañosos. En sentido figurado, describe el proceso de tentación y seducción hacia el pecado o el error. Santiago lo emplea al analizar la anatomía de la tentación: cada persona es «seducida» por su propio deseo. Pedro advierte sobre falsos maestros que «seducen» a almas inestables. El término capta tanto el atractivo de la tentación como su naturaleza engañosa y depredadora: lo que parece deseable oculta un anzuelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1186', 'spa', 'arbol -- planta leñosa perenne, usada literalmente para arboles frutales y figuradamente en parabolas e imagenes apocalipticas', 'arbol -- planta leñosa perenne, usada literalmente para arboles frutales y figuradamente en parabolas e imagenes apocalipticas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1188', 'spa', 'δεξιός — derecho (mano o lado); la posicion de honor, poder y autoridad divina', 'El adjetivo δεξιός (''derecho'') designa la mano derecha o el lado derecho, con peso tanto espacial como teologico a lo largo de 54 apariciones en el Nuevo Testamento. Espacialmente, identifica una parte del cuerpo (Mt 5:29-30) o una posicion en una escena (Mt 25:33, las ovejas a la derecha). Teologicamente, la ''diestra de Dios'' es el asiento supremo de autoridad donde Cristo es exaltado (Mc 16:19; Hch 2:33; Col 3:1), derivado del Salmo 110:1. Tambien significa comunion y comision (Ga 2:9). El espanol ''diestra'' capta fielmente este doble sentido espacial y honorifico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1189', 'spa', 'Rogar o suplicar a una persona; orar o dirigir suplicas a Dios.', 'Rogar o suplicar a una persona; orar o dirigir suplicas a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1191', 'spa', 'Derbe, ciudad de Licaonia donde Pablo ministró e hizo discípulos', 'Derbe era una ciudad en la provincia romana de Galacia, en la región de Licaonia. Representó el límite sureste del primer viaje misionero de Pablo. Tras ser apedreado en Listra y dado por muerto, Pablo viajó a Derbe, donde él y Bernabé hicieron muchos discípulos sin oposición registrada. La ciudad reaparece en Hechos 16 cuando Pablo regresa con Timoteo. Su ubicación la convertía en un punto estratégico para la expansión del evangelio hacia el interior de Asia Menor. Era el hogar de Gayo, uno de los compañeros de viaje de Pablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1193', 'spa', 'hecho de cuero, de cuero; describiendo la composición material', 'Este adjetivo describe artículos hechos de piel animal o cuero. Ambas ocurrencias en el Nuevo Testamento se refieren a la vestimenta distintiva de Juan el Bautista, específicamente su cinturón o cinto de cuero. Este detalle conecta a Juan con la tradición profética, particularmente con Elías, quien vestía atuendo similar. El cinturón de cuero era parte de la apariencia ascética de Juan que lo marcaba como un profeta del desierto llamando a Israel al arrepentimiento. La evidencia multilingüe (español ''de cuero,'' francés ''de cuir,'' alemán ''ledern'') identifica uniformemente esto como un descriptor de material, enfatizando la naturaleza rústica y no lujosa del vestido profético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1194', 'spa', 'Golpear, azotar, flagelar; infligir golpes a alguien, ya sea por violencia o como castigo judicial. Δέρω significaba originalmente ''desollar'' o ''despe', 'Golpear, azotar, flagelar; infligir golpes a alguien, ya sea por violencia o como castigo judicial. Δέρω significaba originalmente ''desollar'' o ''despellejar'' en el griego clásico, pero para la época del NT se había asentado en el sentido de golpear o azotar. Aparece en contextos tanto de violencia informal como de castigo judicial formal. En las parábolas de Jesús, los labradores de la viña golpean a los siervos del dueño (Mt 21:35; Mr 12:3, 5), y un siervo negligente recibe muchos azotes (Lc 12:47-48). En los relatos apostólicos, Pablo y los discípulos son azotados ante concilios y en sinagogas (Mr 13:9; Hch 5:40; 16:37; 22:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1195', 'spa', 'Atar, amarrar o encadenar, ya sea en sentido literal o figurado', 'Este verbo describe la acción de atar o amarrar, ya sea con cuerdas, cadenas u otras ataduras. Puede aplicarse a atar gavillas de trigo, encadenar prisioneros o, en sentido figurado, imponer cargas. Jesús condena a los escribas y fariseos por atar «cargas pesadas» sobre los hombros de la gente sin mover un dedo para ayudarlos. El endemoniado gadareno había sido atado muchas veces con cadenas, pero las rompía. Pablo fue atado y arrastrado durante la persecución. El término evoca confinamiento, restricción e imposición de control.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1196', 'spa', 'atar, amarrar, sujetar; formar ligaduras o vínculos', 'Verbo que significa atar o sujetar cosas entre sí, estrechamente relacionado con δεσμεύω. Los léxicos lo señalan como forma no ática, que aparece en el Nuevo Testamento y en textos griegos posteriores. En voz activa describe la acción de atar o amarrar algo. En voz pasiva indica estar atado o amarrado. En contextos médicos, puede describir articulaciones que sufren anquilosis, es decir, que se vuelven anormalmente rígidas o fusionadas, como si estuvieran atadas entre sí. La palabra transmite el sentido básico de crear conexiones o restricciones mediante la ligadura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1198', 'spa', 'Δέσμιος designa a una persona retenida bajo custodia fisica: atada, encarcelada o detenida por las autoridades. En los Evangelios describe a Barrabas,', 'Δέσμιος designa a una persona retenida bajo custodia fisica: atada, encarcelada o detenida por las autoridades. En los Evangelios describe a Barrabas, el preso notable liberado en la Pascua (Mt 27:15-16; Mr 15:6). En Hechos, Pablo y Silas son prisioneros en Filipos cuya adoracion nocturna desencadena un terremoto (Hch 16:25-27). Pablo luego adopta la identidad de ''prisionero de Cristo Jesus'' (Ef 3:1; Flm 1:1), transformando un termino de verguenza en uno de honor apostolico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1199', 'spa', 'Cadena, atadura o grillete usado para aprisionamiento o restriccion; en sentido figurado, un impedimento que ata el cuerpo o la condicion de una perso', 'Cadena, atadura o grillete usado para aprisionamiento o restriccion; en sentido figurado, un impedimento que ata el cuerpo o la condicion de una persona. En el Nuevo Testamento, δεσμός casi siempre se refiere a las cadenas y grilletes literales del encarcelamiento, apareciendo prominentemente en las cartas de cautividad de Pablo, donde habla de sus ''prisiones'' como insignia de fidelidad apostolica (Fil 1:7, 13; Col 4:18; 2 Ti 2:9; Flm 10, 13). Sin embargo, dos veces se desplaza al terreno figurado, describiendo una atadura invisible sobre alguna facultad de una persona, como cuando Jesus desata la ''atadura'' de la enfermedad de una mujer (Lc 13:16) y la ''atadura'' de la lengua de un hombre (Mr 7:35).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1200', 'spa', 'carcelero, guardián de prisión; encargado de custodiar a los presos en una cárcel o calabozo', 'Un carcelero o guardián de prisión era el responsable de vigilar a los presos y mantener la seguridad del recinto de detención. En el mundo antiguo, este cargo conllevaba una responsabilidad enorme: si los prisioneros escapaban, el carcelero podía enfrentar la pena de muerte. Esto explica el intento de suicidio del carcelero de Filipos cuando supuso que sus prisioneros habían huido durante el terremoto. Su historia de conversión demuestra cómo el evangelio traspasó las barreras sociales, transformando incluso a quienes ejercían la coerción y el encierro en hermanos en Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1201', 'spa', 'cárcel, prisión; lugar de reclusión donde los presos son custodiados bajo guardia', 'δεσμωτήριον designa una cárcel o prisión: un lugar asegurado donde se mantiene a personas bajo custodia. Derivado de δεσμός («atadura, cadena»), subraya el lugar donde se ata al preso, confiriéndole un matiz más institucional que el común φυλακή. En el Nuevo Testamento aparece exclusivamente en los Sinópticos y Hechos: Juan el Bautista envía un mensaje desde el δεσμωτήριον (Mt 11:2), y los apóstoles son liberados milagrosamente de la prisión pública (Hch 5:21-23; 16:26). El sentido es uniforme y concreto: lugar de encarcelamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1202', 'spa', 'prisionero, cautivo; persona retenida bajo cadenas o custodia', 'Este sustantivo designa a una persona mantenida en cautiverio o encarcelamiento, literalmente alguien encadenado o con grilletes. Las dos apariciones en el Nuevo Testamento están en Hechos 27, durante el viaje marítimo de Pablo a Roma como prisionero. El término aparece cuando el centurión entrega a los prisioneros, incluido Pablo, al centurión a cargo (27:1), y más tarde cuando los soldados consideran matar a los prisioneros para evitar su escape durante el naufragio (27:42). La raíz griega se relaciona con ''cadenas'' o ''grilletes'', enfatizando la restricción física del cautiverio. Las traducciones lo presentan consistentemente como ''prisioneros'' en varios idiomas, reflejando su referencia directa a quienes están bajo custodia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1203', 'spa', 'Amo, señor soberano: ya sea dirigiéndose a Dios o a Cristo como gobernante supremo, o a amos humanos de esclavos como señores del hogar. Δεσπότης conl', 'Amo, señor soberano: ya sea dirigiéndose a Dios o a Cristo como gobernante supremo, o a amos humanos de esclavos como señores del hogar. Δεσπότης conlleva el peso de autoridad absoluta y posesión que κύριος no siempre transmite. Cuando Simeón se dirige a Dios como ''Soberano Señor'' (Lucas 2:29) o la iglesia primitiva ora al ''Amo'' que hizo el cielo y la tierra (Hechos 4:24), la palabra evoca la autoridad incuestionable de un propietario sobre toda su casa. La misma palabra se aplica a amos humanos de esclavos, a quienes los esclavos cristianos deben honrar (1 Timoteo 6:1-2; Tito 2:9; 1 Pedro 2:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1204', 'spa', 'Adverbio de movimiento que significa ''acá, ven aquí''; usado como interjección imperativa ''¡ven!'' y temporalmente como ''hasta ahora''.', 'Un versátil adverbio griego enraizado en el movimiento espacial — ''acá'' o ''a este lugar'' — que se desarrolló hasta convertirse en una de las interjecciones imperativas más memorables del Nuevo Testamento. Cuando Jesús exclama δεῦρο ante la tumba de Lázaro (Juan 11:43) o invita al joven rico a seguirle (Mateo 19:21; Marcos 10:21; Lucas 18:22), la palabra lleva una urgencia que resuena en todas las lenguas: español ''¡Ven!'', francés ''viens'', alemán ''komm''. En Romanos 1:13, Pablo extiende la palabra hacia un sentido temporal — ''hasta ahora'' — donde el español lo traduce como ''ahora'', revelando cómo una palabra de aproximación espacial puede deslizarse hacia la noción de llegada temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1205', 'spa', '¡Venid! (imperativo plural) — una invitación o convocatoria que llama a otros a acercarse, seguir o presenciar. La interjección adverbial δεῦτε funcio', '¡Venid! (imperativo plural) — una invitación o convocatoria que llama a otros a acercarse, seguir o presenciar. La interjección adverbial δεῦτε funciona como imperativo plural que significa ''¡venid!'': un llamamiento dirigido a un grupo. Transmite la calidez de la invitación en el gran llamado de Jesús: ''Venid a mí todos los que estáis trabajados y cargados'' (Mt 11:28), y la firmeza de un mandato en ''Venid en pos de mí, y os haré pescadores de hombres'' (Mt 4:19; Mr 1:17). En el juicio final, el Rey dirá: ''Venid, benditos de mi Padre'' (Mt 25:34). Aparece también en la parábola del banquete de bodas (Mt 22:4), en el sepulcro vacío (Mt 28:6; Mr 6:31) y en Juan 4:29 y 21:12.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1207', 'spa', 'sábado segundo-primero (probablemente una corrupción textual en el Nuevo Testamento)', 'Una expresión compuesta enigmática que aparece en algunos manuscritos del Nuevo Testamento y que literalmente significa ''sábado segundo-primero''. Los lexicógrafos generalmente la consideran una corrupción textual más que una expresión griega auténtica, ya que la combinación de ''segundo'' y ''primero'' genera una contradicción aparente. Se han propuesto diversas teorías para explicar su posible significado original: quizá el primer sábado después del segundo día de Pascua, o el segundo sábado en algún sistema de conteo que también era considerado ''primero'' en otro cómputo. La mayoría de los críticos textuales modernos lo consideran un error de copista.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1208', 'spa', 'segundo (ordinal) o por segunda vez (adverbial); indica secuencia, rango o repetición', 'segundo (ordinal) o por segunda vez (adverbial); indica secuencia, rango o repetición');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1209', 'spa', 'Recibir, acoger o aceptar; ofrecer hospitalidad a una persona o aceptar lo que se ofrece, ensena o entrega', 'δέχομαι es una de las palabras mas ricas del Nuevo Testamento para expresar receptividad. Jesus la emplea para definir lo que esta en juego en la mision: ''el que os recibe a vosotros, a mi me recibe'' (Mt 10:40), haciendo del acto de acoger a un discipulo itinerante un encuentro con Cristo mismo. La palabra se extiende desde la hospitalidad fisica — abrir el hogar a un huesped — pasando por la aceptacion intelectual de una ensenanza (Lc 8:13, la semilla que recibe la palabra) hasta el simple acto de tomar un documento en las manos (Lc 16:6). Los contextos griegos distinguen cuidadosamente si lo recibido es una persona, un mensaje o un objeto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1210', 'spa', 'atar, amarrar, sujetar; en sentido figurado, obligar o decretar con autoridad', 'atar, amarrar, sujetar; en sentido figurado, obligar o decretar con autoridad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1211', 'spa', 'Ciertamente, en verdad, pues bien; partícula enfática que añade urgencia, afirmación o fuerza inferencial.', 'Partícula discursiva pequeña pero potente que intensifica o afirma lo que modifica, aportando un matiz de «ciertamente», «en verdad» o «pues bien». Sus raíces son temporales («en este preciso momento»), pero en el Nuevo Testamento funciona principalmente como intensificador retórico. En la parábola del sembrador, la buena tierra «ciertamente» da fruto (Mt 13:23). Los pastores se dicen unos a otros: «Vayamos pues a Belén» (Lc 2:15), donde la partícula añade resolución entusiasta. La iglesia de Antioquía adora y ayuna cuando el Espíritu Santo dice: «Apartadme ahora a Bernabé y a Saulo» (Hch 13:2). Pablo la emplea con énfasis: «Fuisteis comprados por precio; glorificad, pues, a Dios» (1 Co 6:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1212', 'spa', 'claro, evidente, manifiesto, patente; perceptible a la mente o los sentidos, sin dejar lugar a duda', 'Originalmente referido a lo visible a simple vista, δῆλος pasó a denotar lo que resulta claro u obvio para la mente. En las tres apariciones neotestamentarias, indica de manera consistente algo manifiesto más allá de toda duda razonable. El acento galileo de Pedro lo delató como seguidor de Jesús (Mt 26:73). Pablo lo emplea al razonar desde las Escrituras: es «evidente» que cierta excepción aplica (1 Co 15:27) y que nadie se justifica por la ley (Gá 3:11). La palabra transmite no mera visibilidad, sino claridad inequívoca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1213', 'spa', 'Dar a conocer, revelar, indicar, significar; en voz pasiva: ser mostrado o informado a alguien.', 'Δηλόω (deloo) deriva del adjetivo δῆλος (''claro, visible'') y significa fundamentalmente hacer algo manifiesto o evidente. En seis de sus siete apariciones en el NT se usa en voz activa para cubrir diversas acciones revelatorias: el Espíritu de Cristo ''indicaba'' de antemano los sufrimientos del Mesías (1 Pe 1:11), el Espíritu Santo ''da a entender'' que el camino al Lugar Santísimo aún no había sido revelado (Heb 9:8), el Día ''pondrá en claro'' la obra de cada uno (1 Co 3:13), y Epafras ''dio a conocer'' el amor de los colosenses (Col 1:8). La única aparición en voz pasiva (1 Co 1:11) — ''me fue informado'' por los de Cloé — invierte la perspectiva: el sujeto recibe la revelación en vez de ejecutarla. Esta distinción activa-pasiva, aunque numéricamente desigual, tiene peso teológico: Dios revela, y los seres humanos reciben el informe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1214', 'spa', 'Demas, compañero de Pablo que después lo abandonó por amor al mundo presente', 'Demas (posiblemente forma abreviada de Demetrio) fue uno de los colaboradores de Pablo, mencionado junto a Lucas y otros compañeros fieles. Colosenses y Filemón lo registran sirviendo con Pablo durante un encarcelamiento, probablemente en Roma. Sin embargo, 2 Timoteo relata el trágico desenlace: «Demas me ha desamparado, amando este mundo presente, y se ha ido a Tesalónica». Su historia constituye un ejemplo sobrecogedor de un compañero de ministerio que finalmente escogió la seguridad temporal por encima de la fidelidad costosa a Cristo y su evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1216', 'spa', 'Demetrio, nombre de un platero que se opuso a Pablo y de un discípulo cristiano elogiado por Juan', 'Demetrio es un nombre griego que llevan dos personas en el Nuevo Testamento. El primero, un platero de Éfeso, encabezó un motín contra Pablo porque la expansión del evangelio amenazaba el lucrativo comercio de ídolos de Artemisa. El segundo, elogiado por Juan en 3 Juan, recibe un triple testimonio: de la verdad misma, de todos, y de Juan y sus compañeros. El uso dual del nombre recuerda al lector que la identidad no la determina el nombre sino el carácter y la lealtad: un Demetrio se opuso al evangelio por lucro; otro lo ejemplificó con su testimonio fiel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1218', 'spa', 'pueblo, populacho reunido; cuerpo cívico de ciudadanos congregados en contexto público', 'δῆμος se refiere al pueblo entendido como cuerpo cívico o público, especialmente cuando está reunido en asamblea. En el griego clásico abarcaba desde «distrito» hasta «pueblo llano» y «asamblea democrática», pero en sus cuatro apariciones neotestamentarias siempre apunta a una multitud o un populacho actuando colectivamente. El pueblo de Tiro y Sidón busca audiencia por medio de Blasto (Hch 12:22), una turba es agitada en Tesalónica (Hch 17:5), y el δῆμος de Éfeso ruge en el teatro (Hch 19:30, 33). El español «pueblo» capta bien este matiz cívico-colectivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1219', 'spa', 'δημόσιος — público, perteneciente al pueblo; usado adverbialmente: públicamente, a la vista de todos', 'δημόσιος es la forma adjetival de δῆμος (''pueblo'') y significa ''público'' o ''perteneciente a la esfera cívica'', en contraste con lo privado (ἴδιος). En el Nuevo Testamento las cuatro apariciones funcionan adverbialmente en dativo femenino (δημοσίᾳ), con el sentido de ''públicamente, a la vista de todos''. Los apóstoles son puestos en la cárcel pública (Hch 5:18), Pablo protesta por haber sido azotado públicamente sin juicio previo (Hch 16:37), Apolos refuta a sus oponentes en debate público (Hch 18:28) y Pablo enseña tanto públicamente como de casa en casa (Hch 20:20). El término subraya la visibilidad cívica abierta de una acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1220', 'spa', 'Denario: moneda romana de plata equivalente aproximadamente al salario de un dia de un jornalero comun. El δηνάριον era la moneda estandar de plata ro', 'Denario: moneda romana de plata equivalente aproximadamente al salario de un dia de un jornalero comun. El δηνάριον era la moneda estandar de plata romana que circulaba por todas las provincias durante la epoca del Nuevo Testamento. Jesus la utiliza con gran eficacia en su ensenanza: la parabola de los obreros que reciben cada uno un denario sin importar las horas trabajadas (Mt 20:2-13), el siervo que no perdona y que ahoga a un consiervo por una deuda de cien denarios (Mt 18:28), y el famoso episodio de ''dad al Cesar'' donde pregunta de quien es la imagen estampada en la moneda (Mt 22:19-21). La alimentacion de los cinco mil lleva a los discipulos a calcular que doscientos denarios no bastarian para comprar suficiente pan (Mr 6:37; Jn 6:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1222', 'spa', 'sin duda, seguramente, presumiblemente, supongo; quizá, puede ser (en pregunta: implica asentimiento)', 'Adverbio indefinido (propiamente escrito como dos palabras, δή που) que expresa distintos matices de probabilidad según el contexto. En textos trágicos y áticos suele comunicar confianza: ''sin duda'', ''presumo'' o ''seguramente'', y aparece con frecuencia en frases como ''sin duda lo sabes'' o ''ciertamente recuerdas''. En el uso homérico puede significar ''quizá'' o ''puede ser'', con menor grado de certeza. Cuando se emplea en forma interrogativa, generalmente implica una respuesta afirmativa (''¿supongo que lo sabes?'', es decir, ''sí lo sabes''). Con partícula negativa, puede sugerir una expectativa negativa (''¿acaso no es así?'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1223', 'spa', 'A través de (con genitivo); por causa de, a causa de (con acusativo) — paso espacial, duración temporal, instrumentalidad y causación', 'A través de (con genitivo); por causa de, a causa de (con acusativo) — indica paso espacial, duración temporal, instrumentalidad y causación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1224', 'spa', 'cruzar, atravesar, pasar de un lado a otro; trasladarse superando una barrera geográfica o metafísica', 'Este verbo describe el acto de cruzar de un lugar a otro, típicamente atravesando barreras geográficas significativas como cuerpos de agua o regiones extensas. Puede indicar el simple tránsito por un territorio o el acto más dramático de cruzar un mar o un río. El rico en el Hades no puede cruzar el «gran abismo» que lo separa de Abraham. El varón macedonio ruega a Pablo que «pase» a ayudarlos. Los israelitas «atravesaron» el Mar Rojo por fe. El término enfatiza el movimiento a través de fronteras, sean geográficas, espirituales o metafísicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1226', 'spa', 'afirmar con confianza, insistir firmemente; sostener una posición con gran seguridad (voz media)', 'Este verbo en voz media expresa una afirmación o insistencia confiada y enfática sobre una posición. Las dos apariciones en el Nuevo Testamento involucran afirmaciones firmes pero equivocadas: aquellos que desean ser maestros de la ley pero no entienden lo que afirman con confianza (1 Timoteo 1:7), y la instrucción de Pablo de que Tito hable con confianza sobre las buenas obras (Tito 3:8). La voz media sugiere inversión personal en la afirmación—no simplemente declarar hechos sino sostenerlos con seguridad. Las traducciones capturan esto mediante términos como ''confidently assert'' (inglés), ''afirman con certeza'' (español), y ''fest behaupten'' (alemán), todos enfatizando la firmeza y certeza de la afirmación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1227', 'spa', 'Ver con claridad, mirar fijamente o percibir con nitidez y precisión visual', 'Este verbo intensifica el concepto básico de ver, indicando una visión clara, penetrante y precisa. Puede significar mirar fijamente con los ojos bien abiertos o percibir con especial nitidez. Jesús lo emplea en el Sermón del Monte al preguntar cómo alguien puede ofrecer quitar la paja del ojo ajeno sin poder «ver claramente» para quitar la viga del propio. En Marcos, tras un segundo toque, el ciego de Betsaida «miró fijamente» y su vista quedó completamente restaurada. El término subraya la claridad visual y la capacidad de percibir con exactitud.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1228', 'spa', 'el diablo, Satanás como adversario supremo de Dios; también adjetival: calumniador, dado a la acusación maliciosa', 'el diablo, Satanás como adversario supremo de Dios; también adjetival: calumniador, dado a la acusación maliciosa');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1229', 'spa', 'Anunciar, proclamar públicamente, dar aviso o declarar ampliamente', 'Este verbo significa anunciar públicamente, proclamar o difundir noticias de manera amplia. Implica una declaración oficial o enfática destinada a alcanzar una audiencia extensa. Jesús ordena a un aspirante a discípulo que «anuncie el reino de Dios» en lugar de ir primero a enterrar a su padre. Pablo explica a las autoridades romanas los detalles que ha «anunciado» respecto a los ritos de purificación. En Romanos, Pablo recuerda el propósito de Dios con Faraón: que su nombre «sea proclamado en toda la tierra». El término enfatiza el carácter público y extenso del anuncio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1230', 'spa', 'Pasar, transcurrir, referido especialmente a intervalos de tiempo', 'Este verbo describe el paso o transcurso del tiempo. En el uso clásico incluye «atravesar» un período, sobrevivir o vivir a lo largo de ciertos acontecimientos. En el Nuevo Testamento aparece en construcciones temporales que marcan el transcurso entre eventos. Una vez que el sábado «hubo pasado», las mujeres fueron a ungir el cuerpo de Jesús. Cuando «había transcurrido» un tiempo considerable, la navegación se volvió peligrosa. Festo llegó a Cesarea y, después de que «pasaron» algunos días, subió a Jerusalén. El término funciona como marcador narrativo de progresión temporal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1231', 'spa', 'determinar judicialmente, decidir un caso; investigar y llegar a un veredicto', 'Este verbo se refiere a la toma de decisiones judiciales después de la investigación—literalmente ''conocer a fondo'' para emitir juicio. Ambas apariciones están en Hechos, involucrando procedimientos legales. Los líderes judíos piden al comandante romano que traiga a Pablo para poder ''determinar'' su caso con mayor precisión (Hechos 23:15), y Félix más tarde pospone la audiencia de Pablo, diciendo que ''decidirá'' el asunto cuando llegue el tribuno (24:22). El término implica no una decisión arbitraria sino una investigación cuidadosa que conduce a una determinación autoritativa. El contexto judicial es claro por el alemán ''conocer a través'' y el francés ''discerner'', enfatizando el aspecto investigativo antes del veredicto.');